INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8c74a2e3-e347-444d-bef4-f7b14f50e4a9', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Où le fichier peut-il être ouvert ?', '{"question":"Où le fichier peut-il être ouvert ?","answer":"Partout où il y a un navigateur: double-clic depuis un ordinateur, pièce jointe d''e-mail, clé USB, espace de téléchargement de votre site… Il ne fait AUCUN appel à Internet. Et sans JavaScript (impression, très vieux navigateurs), les pages s''affichent quand même, simplement empilées."}', 'Où le fichier peut-il être ouvert ?
Où le fichier peut-il être ouvert ?
