INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('91c71df3-c3c6-46d5-ac04-6f52de341690', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Mon flipbook créé sur ordinateur n''apparaît pas sur mon téléphone — c''est normal ?', '{"question":"Mon flipbook créé sur ordinateur n''apparaît pas sur mon téléphone — c''est normal ?","answer":"Oui: la bibliothèque est rangée dans le navigateur de CHAQUE appareil, elle ne transite par aucun serveur (c''est le principe souverain de booK). Pour passer un flipbook d''un appareil à l''autre: téléchargez le fichier autonome, envoyez-le-vous (AirDrop, e-mail…), puis ré-importez-le avec le bouton nuage — il arrive complet et modifiable. Le fichier EST la sauvegarde."}', 'Mon flipbook créé sur ordinateur n''apparaît pas sur mon téléphone — c''est normal ?
Mon flipbook créé sur ordinateur n''apparaît pas sur mon téléphone — c''est normal ?
Oui: la bibliothèque est rangée dans le navigateur de CHAQUE appareil, elle ne transite par aucun serveur (c''est le principe souverain de booK). Pour passer un flipbook d''un appareil à l''autre: téléchargez le fichier autonome, envoyez-le-vous (AirDrop, e-mail…), puis ré-importez-le avec le bouton nuage — il arrive complet et modifiable. Le fichier EST la sauvegarde.', 'validated', 'import', 'apps:book', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('91c71df3-c3c6-46d5-ac04-6f52de341690', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Mon flipbook créé sur ordinateur n''apparaît pas sur mon téléphone — c''est normal ?', 'Mon flipbook créé sur ordinateur n''apparaît pas sur mon téléphone — c''est normal ?
Mon flipbook créé sur ordinateur n''apparaît pas sur mon téléphone — c''est normal ?
Oui: la bibliothèque est rangée dans le navigateur de CHAQUE appareil, elle ne transite par aucun serveur (c''est le principe souverain de booK). Pour passer un flipbook d''un appareil à l''autre: téléchargez le fichier autonome, envoyez-le-vous (AirDrop, e-mail…), puis ré-importez-le avec le bouton nuage — il arrive complet et modifiable. Le fichier EST la sauvegarde.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('a1021c1c-1462-4dd6-903c-854f95d4d0dd', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'L''import d''un gros PDF échoue sur mon téléphone, que faire ?', '{"question":"L''import d''un gros PDF échoue sur mon téléphone, que faire ?","answer":"La fabrication des pages demande de la mémoire, et les téléphones en ont peu: pour un PDF lourd (plusieurs dizaines de pages ou scans haute résolution), créez le flipbook sur ordinateur, puis transférez le fichier autonome sur le téléphone. Sur mobile, booK réduit automatiquement la finesse des pages pour limiter la casse."}', 'L''import d''un gros PDF échoue sur mon téléphone, que faire ?
L''import d''un gros PDF échoue sur mon téléphone, que faire ?
La fabrication des pages demande de la mémoire, et les téléphones en ont peu: pour un PDF lourd (plusieurs dizaines de pages ou scans haute résolution), créez le flipbook sur ordinateur, puis transférez le fichier autonome sur le téléphone. Sur mobile, booK réduit automatiquement la finesse des pages pour limiter la casse.', 'validated', 'import', 'apps:book', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('a1021c1c-1462-4dd6-903c-854f95d4d0dd', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'L''import d''un gros PDF échoue sur mon téléphone, que faire ?', 'L''import d''un gros PDF échoue sur mon téléphone, que faire ?
L''import d''un gros PDF échoue sur mon téléphone, que faire ?
La fabrication des pages demande de la mémoire, et les téléphones en ont peu: pour un PDF lourd (plusieurs dizaines de pages ou scans haute résolution), créez le flipbook sur ordinateur, puis transférez le fichier autonome sur le téléphone. Sur mobile, booK réduit automatiquement la finesse des pages pour limiter la casse.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('c05d977d-8ced-4693-a151-46fffde7335b', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Mon fichier est lourd, que faire ?', '{"question":"Mon fichier est lourd, que faire ?","answer":"Le poids vient du nombre de pages et de la finesse des visuels (chaque page est déjà recompressée à l''import). Retirez les pages non essentielles, ou repartez d''un PDF exporté en qualité écran plutôt qu''imprimerie. En dessous de 15–20 Mo, tout va bien."}', 'Mon fichier est lourd, que faire ?
Mon fichier est lourd, que faire ?
Le poids vient du nombre de pages et de la finesse des visuels (chaque page est déjà recompressée à l''import). Retirez les pages non essentielles, ou repartez d''un PDF exporté en qualité écran plutôt qu''imprimerie. En dessous de 15–20 Mo, tout va bien.', 'validated', 'import', 'apps:book', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('c05d977d-8ced-4693-a151-46fffde7335b', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Mon fichier est lourd, que faire ?', 'Mon fichier est lourd, que faire ?
Mon fichier est lourd, que faire ?
