INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('23146ce9-cbd2-4952-b81e-6118a6d3ad26', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Mes sessions sont-elles sauvegardées ?', '{"question":"Mes sessions sont-elles sauvegardées ?","answer":"Oui, les 20 dernières sessions restent en bibliothèque locale dans la sidebar Sessions. Vous pouvez les rouvrir, archiver, ou exporter la synthèse en PDF."}', 'Mes sessions sont-elles sauvegardées ?
