INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('39037119-b62d-48ae-817f-7dede6919a8c', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Pourquoi Devil''s Advocate est-il intégré comme rôle système ?', '{"question":"Pourquoi Devil''s Advocate est-il intégré comme rôle système ?","answer":"Pour casser le consensus-bias inhérent aux LLM. Les autres personnalités tendent naturellement vers l''accord poli; Devil''s Advocate a pour mission de remettre en question les hypothèses faibles et les clichés. Sans lui, vous obtiendriez du « shallow output » — c''est notre garde-fou méthodologique."}', 'Pourquoi Devil''s Advocate est-il intégré comme rôle système ?
Pourquoi Devil''s Advocate est-il intégré comme rôle système ?
Pour casser le consensus-bias inhérent aux LLM. Les autres personnalités tendent naturellement vers l''accord poli; Devil''s Advocate a pour mission de remettre en question les hypothèses faibles et les clichés. Sans lui, vous obtiendriez du « shallow output » — c''est notre garde-fou méthodologique.', 'validated', 'import', 'apps:brainstorming', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('39037119-b62d-48ae-817f-7dede6919a8c', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Pourquoi Devil''s Advocate est-il intégré comme rôle système ?', 'Pourquoi Devil''s Advocate est-il intégré comme rôle système ?
Pourquoi Devil''s Advocate est-il intégré comme rôle système ?
Pour casser le consensus-bias inhérent aux LLM. Les autres personnalités tendent naturellement vers l''accord poli; Devil''s Advocate a pour mission de remettre en question les hypothèses faibles et les clichés. Sans lui, vous obtiendriez du « shallow output » — c''est notre garde-fou méthodologique.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('c0db6ebd-f319-4e45-9148-5596f3a5d2b0', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Brainstorming — Pourquoi réfléchir seul plafonne', '{"statement":"Un cerveau isolé suit ses ornières: les mêmes références, les mêmes angles, les mêmes prudences. Ce qui débloque un brainstorming, ce n''est pas plus d''efforts, c''est de la diversité de regards — un stratège, un créatif, un avocat du diable qui s''oppose, quelqu''un qui pense client."}', 'Brainstorming — Pourquoi réfléchir seul plafonne
Un cerveau isolé suit ses ornières: les mêmes références, les mêmes angles, les mêmes prudences. Ce qui débloque un brainstorming, ce n''est pas plus d''efforts, c''est de la diversité de regards — un stratège, un créatif, un avocat du diable qui s''oppose, quelqu''un qui pense client.', 'validated', 'import', 'apps:brainstorming', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('c0db6ebd-f319-4e45-9148-5596f3a5d2b0', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Brainstorming — Pourquoi réfléchir seul plafonne', 'Brainstorming — Pourquoi réfléchir seul plafonne
Un cerveau isolé suit ses ornières: les mêmes références, les mêmes angles, les mêmes prudences. Ce qui débloque un brainstorming, ce n''est pas plus d''efforts, c''est de la diversité de regards — un stratège, un créatif, un avocat du diable qui s''oppose, quelqu''un qui pense client.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('a60d2cca-247d-48eb-8aae-7467a8fba048', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Brainstorming — Recréer le frottement, à plusieurs voix', '{"statement":"Poser un brief clair: un sujet précis (lancement, repositionnement, idéation) donne de la matière à challenger. Confronter les angles: faire dialoguer plusieurs rôles distincts fait surgir des pistes qu''on n''aurait pas explorées seul. Orienter en cours de route: « plus premium », « plus disruptif » — réagir à la discussion vaut mieux que tout cadrer d''avance. Conclure par une synthèse: un échange foisonnant ne sert à rien sans un plan d''actions qui en extrait l''essentiel."}', 'Brainstorming — Recréer le frottement, à plusieurs voix
Poser un brief clair: un sujet précis (lancement, repositionnement, idéation) donne de la matière à challenger. Confronter les angles: faire dialoguer plusieurs rôles distincts fait surgir des pistes qu''on n''aurait pas explorées seul. Orienter en cours de route: « plus premium », « plus disruptif » — réagir à la discussion vaut mieux que tout cadrer d''avance. Conclure par une synthèse: un échange foisonnant ne sert à rien sans un plan d''actions qui en extrait l''essentiel.', 'validated', 'import', 'apps:brainstorming', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('a60d2cca-247d-48eb-8aae-7467a8fba048', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Brainstorming — Recréer le frottement, à plusieurs voix', 'Brainstorming — Recréer le frottement, à plusieurs voix
Poser un brief clair: un sujet précis (lancement, repositionnement, idéation) donne de la matière à challenger. Confronter les angles: faire dialoguer plusieurs rôles distincts fait surgir des pistes qu''on n''aurait pas explorées seul. Orienter en cours de route: « plus premium », « plus disruptif » — réagir à la discussion vaut mieux que tout cadrer d''avance. Conclure par une synthèse: un échange foisonnant ne sert à rien sans un plan d''actions qui en extrait l''essentiel.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('aebe11a4-3376-446c-9ba6-532e8e8a72a3', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Brainstorming — L''idée n''est pas de remplacer votre jugement', '{"statement":"Ces voix ne décident pas à votre place: elles élargissent le champ avant que vous ne tranchiez. Vous restez l''arbitre, mais vous arbitrez entre plus d''options, et plus tôt: les angles morts apparaissent pendant la réflexion, pas une fois le projet lancé. Brainstorming recrée exactement ce comité: neuf personnalités qui dialoguent autour de votre brief, que vous orientez en direct, et une synthèse structurée à la fin."}', 'Brainstorming — L''idée n''est pas de remplacer votre jugement
Ces voix ne décident pas à votre place: elles élargissent le champ avant que vous ne tranchiez. Vous restez l''arbitre, mais vous arbitrez entre plus d''options, et plus tôt: les angles morts apparaissent pendant la réflexion, pas une fois le projet lancé. Brainstorming recrée exactement ce comité: neuf personnalités qui dialoguent autour de votre brief, que vous orientez en direct, et une synthèse structurée à la fin.', 'validated', 'import', 'apps:brainstorming', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('aebe11a4-3376-446c-9ba6-532e8e8a72a3', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Brainstorming — L''idée n''est pas de remplacer votre jugement', 'Brainstorming — L''idée n''est pas de remplacer votre jugement
Ces voix ne décident pas à votre place: elles élargissent le champ avant que vous ne tranchiez. Vous restez l''arbitre, mais vous arbitrez entre plus d''options, et plus tôt: les angles morts apparaissent pendant la réflexion, pas une fois le projet lancé. Brainstorming recrée exactement ce comité: neuf personnalités qui dialoguent autour de votre brief, que vous orientez en direct, et une synthèse structurée à la fin.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('c04bb17e-3e41-4970-bcae-b48a3f9c8d21', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Brief Prod, en une phrase', '{"term":"Brief Prod","definition":"Brief Prod transforme votre intention créative en cahier des charges technique infaillible pour votre graphiste ou votre imprimeur. Évite l''erreur d''impression à 800 €."}', 'Brief Prod, en une phrase
