INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('0b061e34-6baa-4264-bbe3-cd5f21de51fa', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Mes visuels sont-ils stockés en sécurité ?', '{"question":"Mes visuels sont-ils stockés en sécurité ?","answer":"Oui: ils sont stockés dans une base hébergée en Europe, accessibles uniquement par vous via authentification sécurisée. Chaque asset a une URL souveraine (un lien sécurisé) qui apparaît dans le PDF du brief — votre graphiste peut télécharger directement les bons fichiers sans manipulations parallèles."}', 'Mes visuels sont-ils stockés en sécurité ?
Mes visuels sont-ils stockés en sécurité ?
Oui: ils sont stockés dans une base hébergée en Europe, accessibles uniquement par vous via authentification sécurisée. Chaque asset a une URL souveraine (un lien sécurisé) qui apparaît dans le PDF du brief — votre graphiste peut télécharger directement les bons fichiers sans manipulations parallèles.', 'validated', 'import', 'apps:brief-prod', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('0b061e34-6baa-4264-bbe3-cd5f21de51fa', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Mes visuels sont-ils stockés en sécurité ?', 'Mes visuels sont-ils stockés en sécurité ?
