INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('cf75ae24-d0f9-4cc6-bfb9-00a5384cb2c3', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Comment monter un dossier de 10 pages sans le faire page par page ?', '{"question":"Comment monter un dossier de 10 pages sans le faire page par page ?","answer":"Sélectionnez les pages d''un trait (clic sur la première, Maj+clic sur la dernière), puis « Étaler un article » dans la barre du bas: l''article devient titulaire de toutes les pages, marquées « suite » à partir de la deuxième. La même barre applique une rubrique, un contributeur ou fige des pages, en un seul geste."}', 'Comment monter un dossier de 10 pages sans le faire page par page ?
Comment monter un dossier de 10 pages sans le faire page par page ?
Sélectionnez les pages d''un trait (clic sur la première, Maj+clic sur la dernière), puis « Étaler un article » dans la barre du bas: l''article devient titulaire de toutes les pages, marquées « suite » à partir de la deuxième. La même barre applique une rubrique, un contributeur ou fige des pages, en un seul geste.', 'validated', 'import', 'apps:desk', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('cf75ae24-d0f9-4cc6-bfb9-00a5384cb2c3', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Comment monter un dossier de 10 pages sans le faire page par page ?', 'Comment monter un dossier de 10 pages sans le faire page par page ?
Comment monter un dossier de 10 pages sans le faire page par page ?
Sélectionnez les pages d''un trait (clic sur la première, Maj+clic sur la dernière), puis « Étaler un article » dans la barre du bas: l''article devient titulaire de toutes les pages, marquées « suite » à partir de la deuxième. La même barre applique une rubrique, un contributeur ou fige des pages, en un seul geste.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('1fbde60f-1a5c-4f28-beb5-4442a13d9356', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Un contributeur m''a remis sa copie en main propre (clé USB, WeTransfer): comment la faire entrer ?', '{"question":"Un contributeur m''a remis sa copie en main propre (clé USB, WeTransfer): comment la faire entrer ?","answer":"Ouvrez l''onglet « Marbre » et glissez le document dessus — ou cliquez « Importer un article » puis « Choisir un document ». La fiche de l''article s''ouvre avec la pièce déjà jointe et un titre proposé d''après le nom du fichier; complétez rubrique, contributeur et remise, puis « Créer ». L''article attend au marbre avec sa pièce, exactement comme s''il était arrivé par l''adresse e-mail de dépôt. Vous le poserez sur une page quand vous voudrez."}', 'Un contributeur m''a remis sa copie en main propre (clé USB, WeTransfer): comment la faire entrer ?
Un contributeur m''a remis sa copie en main propre (clé USB, WeTransfer): comment la faire entrer ?
Ouvrez l''onglet « Marbre » et glissez le document dessus — ou cliquez « Importer un article » puis « Choisir un document ». La fiche de l''article s''ouvre avec la pièce déjà jointe et un titre proposé d''après le nom du fichier; complétez rubrique, contributeur et remise, puis « Créer ». L''article attend au marbre avec sa pièce, exactement comme s''il était arrivé par l''adresse e-mail de dépôt. Vous le poserez sur une page quand vous voudrez.', 'validated', 'import', 'apps:desk', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('1fbde60f-1a5c-4f28-beb5-4442a13d9356', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Un contributeur m''a remis sa copie en main propre (clé USB, WeTransfer): comment la faire entrer ?', 'Un contributeur m''a remis sa copie en main propre (clé USB, WeTransfer): comment la faire entrer ?
Un contributeur m''a remis sa copie en main propre (clé USB, WeTransfer): comment la faire entrer ?
Ouvrez l''onglet « Marbre » et glissez le document dessus — ou cliquez « Importer un article » puis « Choisir un document ». La fiche de l''article s''ouvre avec la pièce déjà jointe et un titre proposé d''après le nom du fichier; complétez rubrique, contributeur et remise, puis « Créer ». L''article attend au marbre avec sa pièce, exactement comme s''il était arrivé par l''adresse e-mail de dépôt. Vous le poserez sur une page quand vous voudrez.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('51af3c02-fd78-47c9-89dc-9a49c0d64f7c', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Je me suis trompé d''étape (marqué « maquetté » trop tôt): comment revenir ?', '{"question":"Je me suis trompé d''étape (marqué « maquetté » trop tôt): comment revenir ?","answer":"Dans la fiche de la page, touchez l''étape en cours pour la décocher — l''article recule d''un cran — ou touchez une étape passée pour y revenir directement. Avancer se fait toujours d''un cran à la fois. Le chemin de fer suit aussitôt: une page qui n''est plus maquettée reperd sa pleine couleur. Tout reste tracé dans l''historique de l''article."}', 'Je me suis trompé d''étape (marqué « maquetté » trop tôt): comment revenir ?
Je me suis trompé d''étape (marqué « maquetté » trop tôt): comment revenir ?
Dans la fiche de la page, touchez l''étape en cours pour la décocher — l''article recule d''un cran — ou touchez une étape passée pour y revenir directement. Avancer se fait toujours d''un cran à la fois. Le chemin de fer suit aussitôt: une page qui n''est plus maquettée reperd sa pleine couleur. Tout reste tracé dans l''historique de l''article.', 'validated', 'import', 'apps:desk', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('51af3c02-fd78-47c9-89dc-9a49c0d64f7c', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Je me suis trompé d''étape (marqué « maquetté » trop tôt): comment revenir ?', 'Je me suis trompé d''étape (marqué « maquetté » trop tôt): comment revenir ?
Je me suis trompé d''étape (marqué « maquetté » trop tôt): comment revenir ?
Dans la fiche de la page, touchez l''étape en cours pour la décocher — l''article recule d''un cran — ou touchez une étape passée pour y revenir directement. Avancer se fait toujours d''un cran à la fois. Le chemin de fer suit aussitôt: une page qui n''est plus maquettée reperd sa pleine couleur. Tout reste tracé dans l''historique de l''article.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('faa25da9-dad2-4445-b7d2-5809360ee4b3', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Pourquoi certaines pages ne bougent-elles pas quand je repagine ?', '{"question":"Pourquoi certaines pages ne bougent-elles pas quand je repagine ?","answer":"Ce sont les pages figées (couverture, 4ᵉ de couv, publicités vendues, sommaire): elles restent ancrées à leur numéro de page et le contenu coule autour d''elles — une pub vendue « page 30 » reste page 30. Pour les déplacer quand même, cochez « déplacer aussi les figées » dans la barre de sélection."}', 'Pourquoi certaines pages ne bougent-elles pas quand je repagine ?
Pourquoi certaines pages ne bougent-elles pas quand je repagine ?
Ce sont les pages figées (couverture, 4ᵉ de couv, publicités vendues, sommaire): elles restent ancrées à leur numéro de page et le contenu coule autour d''elles — une pub vendue « page 30 » reste page 30. Pour les déplacer quand même, cochez « déplacer aussi les figées » dans la barre de sélection.', 'validated', 'import', 'apps:desk', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('faa25da9-dad2-4445-b7d2-5809360ee4b3', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Pourquoi certaines pages ne bougent-elles pas quand je repagine ?', 'Pourquoi certaines pages ne bougent-elles pas quand je repagine ?
Pourquoi certaines pages ne bougent-elles pas quand je repagine ?
Ce sont les pages figées (couverture, 4ᵉ de couv, publicités vendues, sommaire): elles restent ancrées à leur numéro de page et le contenu coule autour d''elles — une pub vendue « page 30 » reste page 30. Pour les déplacer quand même, cochez « déplacer aussi les figées » dans la barre de sélection.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('b4846dc5-d44f-4825-b1f1-1f16125c827a', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'desK remplace-t-il InDesign ou la relecture ?', '{"question":"desK remplace-t-il InDesign ou la relecture ?","answer":"Non, et c''est voulu. La maquette reste dans InDesign; la relecture de la copie se fait avec Ghost Writer. desK pilote ce qui manque: qui doit livrer quoi, quand, avec quelle marge — et quoi faire quand ça dérape."}', 'desK remplace-t-il InDesign ou la relecture ?
desK remplace-t-il InDesign ou la relecture ?
Non, et c''est voulu. La maquette reste dans InDesign; la relecture de la copie se fait avec Ghost Writer. desK pilote ce qui manque: qui doit livrer quoi, quand, avec quelle marge — et quoi faire quand ça dérape.', 'validated', 'import', 'apps:desk', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('b4846dc5-d44f-4825-b1f1-1f16125c827a', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'desK remplace-t-il InDesign ou la relecture ?', 'desK remplace-t-il InDesign ou la relecture ?
