INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('726af1fe-61ae-41c2-b6ee-33c4440d9bdc', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Mes contributeurs doivent-ils utiliser l''application ?', '{"question":"Mes contributeurs doivent-ils utiliser l''application ?","answer":"Jamais. Ils continuent d''envoyer leurs textes par e-mail comme ils l''ont toujours fait. Vous pointez « copie reçue » en un clic. L''adresse de dépôt qui range toute seule les contributions arrive dans une prochaine version."}', 'Mes contributeurs doivent-ils utiliser l''application ?
