INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('726af1fe-61ae-41c2-b6ee-33c4440d9bdc', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Mes contributeurs doivent-ils utiliser l''application ?', 'Mes contributeurs doivent-ils utiliser l''application ?
