INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('69428e62-3a9e-4680-aab5-f173405b7152', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'La numérotation ne colle pas à ma maquette (couvertures à part, numéro de départ) ?', '{"question":"La numérotation ne colle pas à ma maquette (couvertures à part, numéro de départ) ?","answer":"Deux réglages se complètent. Dans Réglages → Numérotation, le style d''ensemble: couverture hors numérotation et numéro de départ de la page suivante. Puis, pour un cas particulier, ouvrez la fiche de la page concernée → section « Numérotation »: « Hors numérotation » sort la page du compte (elle s''affiche 2ᵉ, 3ᵉ ou 4ᵉ de couverture selon sa place — le cas du cahier de couverture qui entoure l''intérieur), « Numéro imposé » lui donne le numéro que vous tapez et toute la suite se recale d''elle-même, même chemin de fer déjà construit. L''ordre réel des pages ne change jamais (glisser-déposer et pré-impression restent fiables): seul le numéro affiché change, et ce réglage est réservé au propriétaire de la publication."}', 'La numérotation ne colle pas à ma maquette (couvertures à part, numéro de départ) ?
La numérotation ne colle pas à ma maquette (couvertures à part, numéro de départ) ?
Deux réglages se complètent. Dans Réglages → Numérotation, le style d''ensemble: couverture hors numérotation et numéro de départ de la page suivante. Puis, pour un cas particulier, ouvrez la fiche de la page concernée → section « Numérotation »: « Hors numérotation » sort la page du compte (elle s''affiche 2ᵉ, 3ᵉ ou 4ᵉ de couverture selon sa place — le cas du cahier de couverture qui entoure l''intérieur), « Numéro imposé » lui donne le numéro que vous tapez et toute la suite se recale d''elle-même, même chemin de fer déjà construit. L''ordre réel des pages ne change jamais (glisser-déposer et pré-impression restent fiables): seul le numéro affiché change, et ce réglage est réservé au propriétaire de la publication.', 'validated', 'import', 'apps:desk', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('69428e62-3a9e-4680-aab5-f173405b7152', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'La numérotation ne colle pas à ma maquette (couvertures à part, numéro de départ) ?', 'La numérotation ne colle pas à ma maquette (couvertures à part, numéro de départ) ?
La numérotation ne colle pas à ma maquette (couvertures à part, numéro de départ) ?
Deux réglages se complètent. Dans Réglages → Numérotation, le style d''ensemble: couverture hors numérotation et numéro de départ de la page suivante. Puis, pour un cas particulier, ouvrez la fiche de la page concernée → section « Numérotation »: « Hors numérotation » sort la page du compte (elle s''affiche 2ᵉ, 3ᵉ ou 4ᵉ de couverture selon sa place — le cas du cahier de couverture qui entoure l''intérieur), « Numéro imposé » lui donne le numéro que vous tapez et toute la suite se recale d''elle-même, même chemin de fer déjà construit. L''ordre réel des pages ne change jamais (glisser-déposer et pré-impression restent fiables): seul le numéro affiché change, et ce réglage est réservé au propriétaire de la publication.');
