INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8113c9b0-3495-4edf-8d88-29565e2e30a7', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Ghost Writer · ✦ Passe IA approfondie', '{"statement":"✦ Passe IA approfondie: une fois l''orthographe corrigée, demandez à l''IA d''améliorer le style et les tournures (consomme votre quota Ghost Writer)."}', 'Ghost Writer · ✦ Passe IA approfondie
✦ Passe IA approfondie: une fois l''orthographe corrigée, demandez à l''IA d''améliorer le style et les tournures (consomme votre quota Ghost Writer).', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8113c9b0-3495-4edf-8d88-29565e2e30a7', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Ghost Writer · ✦ Passe IA approfondie', 'Ghost Writer · ✦ Passe IA approfondie
✦ Passe IA approfondie: une fois l''orthographe corrigée, demandez à l''IA d''améliorer le style et les tournures (consomme votre quota Ghost Writer).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('497a455f-d1f1-483b-ab97-fa7124e7b1dc', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Mon texte ou mon PDF sont-ils envoyés sur Internet ?', '{"question":"Mon texte ou mon PDF sont-ils envoyés sur Internet ?","answer":"Non. La détection des fautes tourne à 100 % dans votre navigateur (moteur Grammalecte, hors-ligne). Votre PDF ne quitte jamais votre machine. Seule la « Passe IA approfondie » optionnelle envoie le texte à l''IA, et uniquement quand vous cliquez dessus."}', 'Mon texte ou mon PDF sont-ils envoyés sur Internet ?
Mon texte ou mon PDF sont-ils envoyés sur Internet ?
Non. La détection des fautes tourne à 100 % dans votre navigateur (moteur Grammalecte, hors-ligne). Votre PDF ne quitte jamais votre machine. Seule la « Passe IA approfondie » optionnelle envoie le texte à l''IA, et uniquement quand vous cliquez dessus.', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('497a455f-d1f1-483b-ab97-fa7124e7b1dc', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Mon texte ou mon PDF sont-ils envoyés sur Internet ?', 'Mon texte ou mon PDF sont-ils envoyés sur Internet ?
Mon texte ou mon PDF sont-ils envoyés sur Internet ?
Non. La détection des fautes tourne à 100 % dans votre navigateur (moteur Grammalecte, hors-ligne). Votre PDF ne quitte jamais votre machine. Seule la « Passe IA approfondie » optionnelle envoie le texte à l''IA, et uniquement quand vous cliquez dessus.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('0cc4255c-1104-4f7a-897e-27f323d1241a', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Quel moteur corrige l''orthographe et la grammaire ?', '{"question":"Quel moteur corrige l''orthographe et la grammaire ?","answer":"Grammalecte, un correcteur grammatical français open source (licence GPL v3), exécuté localement. Keystone l''utilise tel quel, sans le modifier. Crédit et lien vers la source sont affichés en bas du correcteur (grammalecte.net)."}', 'Quel moteur corrige l''orthographe et la grammaire ?
Quel moteur corrige l''orthographe et la grammaire ?
Grammalecte, un correcteur grammatical français open source (licence GPL v3), exécuté localement. Keystone l''utilise tel quel, sans le modifier. Crédit et lien vers la source sont affichés en bas du correcteur (grammalecte.net).', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('0cc4255c-1104-4f7a-897e-27f323d1241a', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Quel moteur corrige l''orthographe et la grammaire ?', 'Quel moteur corrige l''orthographe et la grammaire ?
Quel moteur corrige l''orthographe et la grammaire ?
Grammalecte, un correcteur grammatical français open source (licence GPL v3), exécuté localement. Keystone l''utilise tel quel, sans le modifier. Crédit et lien vers la source sont affichés en bas du correcteur (grammalecte.net).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('0b6e7ffb-ace1-4e47-a660-b88936aa210e', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Les PDF scannés (photos) sont-ils gérés ?', '{"question":"Les PDF scannés (photos) sont-ils gérés ?","answer":"Pas encore. Le correcteur a besoin d''une couche texte (PDF « texte », sélectionnable). Une page scannée (image) est détectée et signalée comme non supportée. La reconnaissance de texte (OCR) viendra plus tard."}', 'Les PDF scannés (photos) sont-ils gérés ?
Les PDF scannés (photos) sont-ils gérés ?
Pas encore. Le correcteur a besoin d''une couche texte (PDF « texte », sélectionnable). Une page scannée (image) est détectée et signalée comme non supportée. La reconnaissance de texte (OCR) viendra plus tard.', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('0b6e7ffb-ace1-4e47-a660-b88936aa210e', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Les PDF scannés (photos) sont-ils gérés ?', 'Les PDF scannés (photos) sont-ils gérés ?
Les PDF scannés (photos) sont-ils gérés ?
Pas encore. Le correcteur a besoin d''une couche texte (PDF « texte », sélectionnable). Une page scannée (image) est détectée et signalée comme non supportée. La reconnaissance de texte (OCR) viendra plus tard.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('9861c1bc-41de-45fa-a62e-ef790ddfe28c', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Pourquoi le correcteur est-il gratuit mais pas la passe IA ?', '{"question":"Pourquoi le correcteur est-il gratuit mais pas la passe IA ?","answer":"La détection Grammalecte est locale et gratuite, sans limite. Seule la « Passe IA approfondie » (style, reformulation) consomme votre quota Ghost Writer, car elle fait appel à un modèle IA."}', 'Pourquoi le correcteur est-il gratuit mais pas la passe IA ?
Pourquoi le correcteur est-il gratuit mais pas la passe IA ?
La détection Grammalecte est locale et gratuite, sans limite. Seule la « Passe IA approfondie » (style, reformulation) consomme votre quota Ghost Writer, car elle fait appel à un modèle IA.', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('9861c1bc-41de-45fa-a62e-ef790ddfe28c', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Pourquoi le correcteur est-il gratuit mais pas la passe IA ?', 'Pourquoi le correcteur est-il gratuit mais pas la passe IA ?
Pourquoi le correcteur est-il gratuit mais pas la passe IA ?
La détection Grammalecte est locale et gratuite, sans limite. Seule la « Passe IA approfondie » (style, reformulation) consomme votre quota Ghost Writer, car elle fait appel à un modèle IA.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('02cf1a21-d7d4-42cc-8d3b-131bbb555182', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Le « PDF annoté » modifie-t-il mon document d''origine ?', '{"question":"Le « PDF annoté » modifie-t-il mon document d''origine ?","answer":"Non. Il crée une copie: vos fautes sont surlignées par-dessus sans toucher la mise en page, et une page récapitulative est ajoutée à la fin. Le texte du PDF n''est jamais réécrit à votre place."}', 'Le « PDF annoté » modifie-t-il mon document d''origine ?
Le « PDF annoté » modifie-t-il mon document d''origine ?
Non. Il crée une copie: vos fautes sont surlignées par-dessus sans toucher la mise en page, et une page récapitulative est ajoutée à la fin. Le texte du PDF n''est jamais réécrit à votre place.', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('02cf1a21-d7d4-42cc-8d3b-131bbb555182', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Le « PDF annoté » modifie-t-il mon document d''origine ?', 'Le « PDF annoté » modifie-t-il mon document d''origine ?
Le « PDF annoté » modifie-t-il mon document d''origine ?
Non. Il crée une copie: vos fautes sont surlignées par-dessus sans toucher la mise en page, et une page récapitulative est ajoutée à la fin. Le texte du PDF n''est jamais réécrit à votre place.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8435baed-00fa-41fb-9440-106afb7d0def', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Le premier lancement du correcteur est un peu long, normal ?', '{"question":"Le premier lancement du correcteur est un peu long, normal ?","answer":"Oui: le dictionnaire français (~9 Mo) se charge au premier usage, puis il est gardé en cache pour les fois suivantes (y compris hors-ligne). Les analyses suivantes sont quasi instantanées."}', 'Le premier lancement du correcteur est un peu long, normal ?
Le premier lancement du correcteur est un peu long, normal ?
Oui: le dictionnaire français (~9 Mo) se charge au premier usage, puis il est gardé en cache pour les fois suivantes (y compris hors-ligne). Les analyses suivantes sont quasi instantanées.', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8435baed-00fa-41fb-9440-106afb7d0def', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Le premier lancement du correcteur est un peu long, normal ?', 'Le premier lancement du correcteur est un peu long, normal ?
Le premier lancement du correcteur est un peu long, normal ?
Oui: le dictionnaire français (~9 Mo) se charge au premier usage, puis il est gardé en cache pour les fois suivantes (y compris hors-ligne). Les analyses suivantes sont quasi instantanées.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('54d28a4a-5d08-47b6-9f7c-ce38678e969d', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Ghost Writer — D''où vient le ton « robotique »', '{"statement":"Un modèle vise la formulation la plus probable, donc la plus moyenne. Sans cadrage, il produit du lisse: ni faux, ni faux pas, mais sans voix. Le correctif n''est pas d''écrire moins bien, c''est de donner un contexte précis — à qui vous parlez, sur quel ton, dans quel cadre."}', 'Ghost Writer — D''où vient le ton « robotique »
Un modèle vise la formulation la plus probable, donc la plus moyenne. Sans cadrage, il produit du lisse: ni faux, ni faux pas, mais sans voix. Le correctif n''est pas d''écrire moins bien, c''est de donner un contexte précis — à qui vous parlez, sur quel ton, dans quel cadre.', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('54d28a4a-5d08-47b6-9f7c-ce38678e969d', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Ghost Writer — D''où vient le ton « robotique »', 'Ghost Writer — D''où vient le ton « robotique »
Un modèle vise la formulation la plus probable, donc la plus moyenne. Sans cadrage, il produit du lisse: ni faux, ni faux pas, mais sans voix. Le correctif n''est pas d''écrire moins bien, c''est de donner un contexte précis — à qui vous parlez, sur quel ton, dans quel cadre.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('c3175d39-0ebd-46a0-89b1-e4339a7f82a5', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Ghost Writer — Les bons réflexes', '{"statement":"Choisir le registre: un e-mail pro, une note interne et un texte marketing n''ont ni la même longueur ni la même chaleur. Calibrez avant d''écrire. Comparer des variantes: produire plusieurs versions d''un même message et garder ce qui sonne vous, plutôt que d''accepter la première sortie. Garder la main: couper les superlatifs, raccourcir, réinjecter un détail concret que seule votre activité connaît. Relire pour de vrai: l''orthographe et les accords se vérifient à part — idéalement en local, sans envoyer votre texte sur un serveur tiers. Ghost Writer suit cette logique: trois variantes calibrées selon le contexte pour trouver votre ton, et un correcteur orthographique qui travaille sur votre appareil, sans rien envoyer en ligne."}', 'Ghost Writer — Les bons réflexes
Choisir le registre: un e-mail pro, une note interne et un texte marketing n''ont ni la même longueur ni la même chaleur. Calibrez avant d''écrire. Comparer des variantes: produire plusieurs versions d''un même message et garder ce qui sonne vous, plutôt que d''accepter la première sortie. Garder la main: couper les superlatifs, raccourcir, réinjecter un détail concret que seule votre activité connaît. Relire pour de vrai: l''orthographe et les accords se vérifient à part — idéalement en local, sans envoyer votre texte sur un serveur tiers. Ghost Writer suit cette logique: trois variantes calibrées selon le contexte pour trouver votre ton, et un correcteur orthographique qui travaille sur votre appareil, sans rien envoyer en ligne.', 'validated', 'import', 'apps:ghost-writer', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('c3175d39-0ebd-46a0-89b1-e4339a7f82a5', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Ghost Writer — Les bons réflexes', 'Ghost Writer — Les bons réflexes
Choisir le registre: un e-mail pro, une note interne et un texte marketing n''ont ni la même longueur ni la même chaleur. Calibrez avant d''écrire. Comparer des variantes: produire plusieurs versions d''un même message et garder ce qui sonne vous, plutôt que d''accepter la première sortie. Garder la main: couper les superlatifs, raccourcir, réinjecter un détail concret que seule votre activité connaît. Relire pour de vrai: l''orthographe et les accords se vérifient à part — idéalement en local, sans envoyer votre texte sur un serveur tiers. Ghost Writer suit cette logique: trois variantes calibrées selon le contexte pour trouver votre ton, et un correcteur orthographique qui travaille sur votre appareil, sans rien envoyer en ligne.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('d2eef8fc-f951-4247-83b0-854c008f64de', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Key Brand, en une phrase', '{"term":"Key Brand","definition":"Key Brand transforme votre charte graphique en mini-site interactif: logo téléchargeable au bon format, couleurs copiables avec tests de contraste, typographies à l''essai, règles d''usage générées avec votre logo. Une charte par marque, partageable d''un lien — toujours à jour, sans PDF."}', 'Key Brand, en une phrase
Key Brand
Key Brand transforme votre charte graphique en mini-site interactif: logo téléchargeable au bon format, couleurs copiables avec tests de contraste, typographies à l''essai, règles d''usage générées avec votre logo. Une charte par marque, partageable d''un lien — toujours à jour, sans PDF.', 'validated', 'import', 'apps:key-brand', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('d2eef8fc-f951-4247-83b0-854c008f64de', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Key Brand, en une phrase', 'Key Brand, en une phrase
