Key Brand transforme votre charte graphique en mini-site interactif: logo téléchargeable au bon format, couleurs copiables avec tests de contraste, typographies à l''essai, règles d''usage générées avec votre logo. Une charte par marque, partageable d''un lien — toujours à jour, sans PDF.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('6ffa5f3e-3b78-47d4-942d-d9c7d20848be', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Key Brand · Créer une charte', '{"statement":"Créer une charte: bouton « Nouvelle charte », donnez-lui le nom de la marque — la vôtre ou celle d''un client (jusqu''à 30 chartes par compte)."}', 'Key Brand · Créer une charte
Créer une charte: bouton « Nouvelle charte », donnez-lui le nom de la marque — la vôtre ou celle d''un client (jusqu''à 30 chartes par compte).', 'validated', 'import', 'apps:key-brand', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('6ffa5f3e-3b78-47d4-942d-d9c7d20848be', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Key Brand · Créer une charte', 'Key Brand · Créer une charte
