INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('884da2f0-b535-4846-b596-989686c4f707', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Combien de temps les réponses sont-elles conservées ?', '{"question":"Combien de temps les réponses sont-elles conservées ?","answer":"Selon la TTL que vous avez choisie (30, 90, 180 ou 365 jours). Après expiration, suppression automatique côté serveur — conformité RGPD Art. 5 native. Le mail Resend reste dans la boîte du destinataire indéfiniment."}', 'Combien de temps les réponses sont-elles conservées ?
