INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8bf30dff-8239-4054-b300-dbb889c319b5', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Comment partager le formulaire avec mes répondants ?', '{"question":"Comment partager le formulaire avec mes répondants ?","answer":"Une fois publié, copiez l''URL keystone.app/f/{votre-slug} et envoyez-la par mail, SMS, Slack ou QR code. Aucune installation nécessaire pour le répondant."}', 'Comment partager le formulaire avec mes répondants ?
Comment partager le formulaire avec mes répondants ?
Une fois publié, copiez l''URL keystone.app/f/{votre-slug} et envoyez-la par mail, SMS, Slack ou QR code. Aucune installation nécessaire pour le répondant.', 'validated', 'import', 'apps:key-form', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8bf30dff-8239-4054-b300-dbb889c319b5', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Comment partager le formulaire avec mes répondants ?', 'Comment partager le formulaire avec mes répondants ?
