INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('a3da5bef-d48c-4e47-9c69-20d1023da606', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Puis-je dupliquer un formulaire existant ?', 'Puis-je dupliquer un formulaire existant ?
Puis-je dupliquer un formulaire existant ?
