INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('6f8bf0fd-410f-4334-8c72-c87bfe6c1db1', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Comment fonctionne la logique conditionnelle ?', '{"question":"Comment fonctionne la logique conditionnelle ?","answer":"Sélectionnez un champ dans le builder, puis dans l''éditeur de droite ouvrez ''Visibilité conditionnelle'' ou ''Obligatoire conditionnel''. Vous pouvez aussi configurer une somme automatique entre champs Montant."}', 'Comment fonctionne la logique conditionnelle ?
Comment fonctionne la logique conditionnelle ?
Sélectionnez un champ dans le builder, puis dans l''éditeur de droite ouvrez ''Visibilité conditionnelle'' ou ''Obligatoire conditionnel''. Vous pouvez aussi configurer une somme automatique entre champs Montant.', 'validated', 'import', 'apps:key-form', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('6f8bf0fd-410f-4334-8c72-c87bfe6c1db1', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Comment fonctionne la logique conditionnelle ?', 'Comment fonctionne la logique conditionnelle ?
Comment fonctionne la logique conditionnelle ?
Sélectionnez un champ dans le builder, puis dans l''éditeur de droite ouvrez ''Visibilité conditionnelle'' ou ''Obligatoire conditionnel''. Vous pouvez aussi configurer une somme automatique entre champs Montant.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('c41b7a40-23b9-4d28-92c9-bc2088a05d79', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Puis-je pré-remplir des champs via l''URL ?', '{"question":"Puis-je pré-remplir des champs via l''URL ?","answer":"Oui: chaque champ a un ID technique (visible dans son éditeur) qui peut être utilisé en query param. Exemple: keystone.app/f/biennale?fld_nom=Marie+Durand."}', 'Puis-je pré-remplir des champs via l''URL ?
Puis-je pré-remplir des champs via l''URL ?
Oui: chaque champ a un ID technique (visible dans son éditeur) qui peut être utilisé en query param. Exemple: keystone.app/f/biennale?fld_nom=Marie+Durand.', 'validated', 'import', 'apps:key-form', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('c41b7a40-23b9-4d28-92c9-bc2088a05d79', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Puis-je pré-remplir des champs via l''URL ?', 'Puis-je pré-remplir des champs via l''URL ?
