INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('65febfd9-e59f-44a6-8a02-2306a4725f69', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Quels types de fichiers les répondants peuvent-ils joindre ?', '{"question":"Quels types de fichiers les répondants peuvent-ils joindre ?","answer":"Pas d''upload direct. À la place, utilisez le type ''Lien externe'': le répondant colle un lien WeTransfer, Drive, Dropbox ou Vimeo."}', 'Quels types de fichiers les répondants peuvent-ils joindre ?
Quels types de fichiers les répondants peuvent-ils joindre ?
Pas d''upload direct. À la place, utilisez le type ''Lien externe'': le répondant colle un lien WeTransfer, Drive, Dropbox ou Vimeo.', 'validated', 'import', 'apps:key-form', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('65febfd9-e59f-44a6-8a02-2306a4725f69', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Quels types de fichiers les répondants peuvent-ils joindre ?', 'Quels types de fichiers les répondants peuvent-ils joindre ?
Quels types de fichiers les répondants peuvent-ils joindre ?
Pas d''upload direct. À la place, utilisez le type ''Lien externe'': le répondant colle un lien WeTransfer, Drive, Dropbox ou Vimeo.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('d2ec2ab4-2dfa-448b-9fab-d959b61461b7', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Key Form — L''alternative aux formulaires classiques', '{"statement":"Construire un formulaire est aujourd''hui à la portée de tous: on choisit ses champs, on rédige ses questions, on partage un lien. Pas de code, pas d''hébergement à gérer. Le vrai sujet n''est plus technique, il est juridique."}', 'Key Form — L''alternative aux formulaires classiques
Construire un formulaire est aujourd''hui à la portée de tous: on choisit ses champs, on rédige ses questions, on partage un lien. Pas de code, pas d''hébergement à gérer. Le vrai sujet n''est plus technique, il est juridique.', 'validated', 'import', 'apps:key-form', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('d2ec2ab4-2dfa-448b-9fab-d959b61461b7', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Key Form — L''alternative aux formulaires classiques', 'Key Form — L''alternative aux formulaires classiques
Construire un formulaire est aujourd''hui à la portée de tous: on choisit ses champs, on rédige ses questions, on partage un lien. Pas de code, pas d''hébergement à gérer. Le vrai sujet n''est plus technique, il est juridique.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8caec24c-5423-4e82-b8f1-e415102c2676', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Key Form — Pourquoi le RGPD compte ici', '{"statement":"Un formulaire collecte presque toujours des données personnelles — nom, e-mail, parfois plus. Beaucoup d''outils gratuits stockent ces réponses sur des serveurs hors d''Europe, les analysent, voire les monétisent. Vous restez pourtant responsable de ce que deviennent les données de vos répondants. Consentement clair: la personne sait à quoi elle s''engage en répondant. Données maîtrisées: pas de revente, pas de traceurs publicitaires greffés sur votre formulaire. Hébergement maîtrisé: savoir où les réponses sont conservées, et pouvoir les supprimer. Minimisation: ne demander que les champs réellement utiles. Moins vous collectez, moins vous portez de risque. Ces principes ne sont pas un luxe juridique: ils protègent vos répondants et vous évitent d''engager votre responsabilité sans le savoir, pour un simple formulaire de contact."}', 'Key Form — Pourquoi le RGPD compte ici
Un formulaire collecte presque toujours des données personnelles — nom, e-mail, parfois plus. Beaucoup d''outils gratuits stockent ces réponses sur des serveurs hors d''Europe, les analysent, voire les monétisent. Vous restez pourtant responsable de ce que deviennent les données de vos répondants. Consentement clair: la personne sait à quoi elle s''engage en répondant. Données maîtrisées: pas de revente, pas de traceurs publicitaires greffés sur votre formulaire. Hébergement maîtrisé: savoir où les réponses sont conservées, et pouvoir les supprimer. Minimisation: ne demander que les champs réellement utiles. Moins vous collectez, moins vous portez de risque. Ces principes ne sont pas un luxe juridique: ils protègent vos répondants et vous évitent d''engager votre responsabilité sans le savoir, pour un simple formulaire de contact.', 'validated', 'import', 'apps:key-form', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8caec24c-5423-4e82-b8f1-e415102c2676', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Key Form — Pourquoi le RGPD compte ici', 'Key Form — Pourquoi le RGPD compte ici
Un formulaire collecte presque toujours des données personnelles — nom, e-mail, parfois plus. Beaucoup d''outils gratuits stockent ces réponses sur des serveurs hors d''Europe, les analysent, voire les monétisent. Vous restez pourtant responsable de ce que deviennent les données de vos répondants. Consentement clair: la personne sait à quoi elle s''engage en répondant. Données maîtrisées: pas de revente, pas de traceurs publicitaires greffés sur votre formulaire. Hébergement maîtrisé: savoir où les réponses sont conservées, et pouvoir les supprimer. Minimisation: ne demander que les champs réellement utiles. Moins vous collectez, moins vous portez de risque. Ces principes ne sont pas un luxe juridique: ils protègent vos répondants et vous évitent d''engager votre responsabilité sans le savoir, pour un simple formulaire de contact.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('aec3bb22-7c16-41ac-b6da-361c1216566d', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Key Form — Partager simplement', '{"statement":"Un bon formulaire se diffuse par un simple lien ou un QR code — sur une affiche, un e-mail, un comptoir. Le répondant ouvre, remplit, valide; vous récupérez des réponses propres, sans friction. Key Form réunit ces deux exigences: la simplicité d''un formulaire sans code et la conformité RGPD par défaut, partageable par lien ou QR."}', 'Key Form — Partager simplement
Un bon formulaire se diffuse par un simple lien ou un QR code — sur une affiche, un e-mail, un comptoir. Le répondant ouvre, remplit, valide; vous récupérez des réponses propres, sans friction. Key Form réunit ces deux exigences: la simplicité d''un formulaire sans code et la conformité RGPD par défaut, partageable par lien ou QR.', 'validated', 'import', 'apps:key-form', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('aec3bb22-7c16-41ac-b6da-361c1216566d', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Key Form — Partager simplement', 'Key Form — Partager simplement
Un bon formulaire se diffuse par un simple lien ou un QR code — sur une affiche, un e-mail, un comptoir. Le répondant ouvre, remplit, valide; vous récupérez des réponses propres, sans friction. Key Form réunit ces deux exigences: la simplicité d''un formulaire sans code et la conformité RGPD par défaut, partageable par lien ou QR.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('9cd696d7-fa90-410a-acd5-a5b49ebde5af', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Keynapse, en une phrase', '{"term":"Keynapse","definition":"Votre espace personnel de connaissances. Des bulles de notes qui respirent sur un canevas infini, regroupées en zones de couleur et reliées par des traits. Chaque bulle s''ouvre dans un panneau où vous écrivez, cochez des tâches, attachez des photos, des croquis et des mémos vocaux (que l''IA transcrit et transforme en tâches ou rappels), et posez des rappels qui vous préviennent à l''heure dite. Vos notes restent privées: rien n''est publié."}', 'Keynapse, en une phrase
Keynapse
Votre espace personnel de connaissances. Des bulles de notes qui respirent sur un canevas infini, regroupées en zones de couleur et reliées par des traits. Chaque bulle s''ouvre dans un panneau où vous écrivez, cochez des tâches, attachez des photos, des croquis et des mémos vocaux (que l''IA transcrit et transforme en tâches ou rappels), et posez des rappels qui vous préviennent à l''heure dite. Vos notes restent privées: rien n''est publié.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('9cd696d7-fa90-410a-acd5-a5b49ebde5af', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse, en une phrase', 'Keynapse, en une phrase
Keynapse
Votre espace personnel de connaissances. Des bulles de notes qui respirent sur un canevas infini, regroupées en zones de couleur et reliées par des traits. Chaque bulle s''ouvre dans un panneau où vous écrivez, cochez des tâches, attachez des photos, des croquis et des mémos vocaux (que l''IA transcrit et transforme en tâches ou rappels), et posez des rappels qui vous préviennent à l''heure dite. Vos notes restent privées: rien n''est publié.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('9a1a8aa5-2632-47c3-ad68-fd6540493ec3', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse · Créer une bulle', '{"statement":"Créer une bulle: le bouton « + » crée une bulle dans la vue courante. Un clic sur une bulle ouvre son panneau (à droite sur ordinateur, en bas sur mobile). Glissez une bulle pour la déplacer, sa position est mémorisée."}', 'Keynapse · Créer une bulle
Créer une bulle: le bouton « + » crée une bulle dans la vue courante. Un clic sur une bulle ouvre son panneau (à droite sur ordinateur, en bas sur mobile). Glissez une bulle pour la déplacer, sa position est mémorisée.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('9a1a8aa5-2632-47c3-ad68-fd6540493ec3', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse · Créer une bulle', 'Keynapse · Créer une bulle
Créer une bulle: le bouton « + » crée une bulle dans la vue courante. Un clic sur une bulle ouvre son panneau (à droite sur ordinateur, en bas sur mobile). Glissez une bulle pour la déplacer, sa position est mémorisée.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('1058b276-45fd-41af-b7d5-dc9fc3a0ac38', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse · Naviguer le canevas', '{"statement":"Naviguer le canevas: molette ou pincement pour zoomer, glisser le fond pour vous déplacer. « Tout voir » recadre sur l''ensemble de vos bulles. De loin vous voyez les zones, de près le détail."}', 'Keynapse · Naviguer le canevas
Naviguer le canevas: molette ou pincement pour zoomer, glisser le fond pour vous déplacer. « Tout voir » recadre sur l''ensemble de vos bulles. De loin vous voyez les zones, de près le détail.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('1058b276-45fd-41af-b7d5-dc9fc3a0ac38', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse · Naviguer le canevas', 'Keynapse · Naviguer le canevas
Naviguer le canevas: molette ou pincement pour zoomer, glisser le fond pour vous déplacer. « Tout voir » recadre sur l''ensemble de vos bulles. De loin vous voyez les zones, de près le détail.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('df10d3c4-374f-46b9-a069-992fdaa6e662', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse · Ranger en zones', '{"statement":"Ranger en zones: le bouton Zones ouvre le gestionnaire (créer, renommer, recolorer, aller à une zone). Les bulles d''une même zone partagent sa couleur et se regroupent doucement. Une bulle peut rester libre."}', 'Keynapse · Ranger en zones
Ranger en zones: le bouton Zones ouvre le gestionnaire (créer, renommer, recolorer, aller à une zone). Les bulles d''une même zone partagent sa couleur et se regroupent doucement. Une bulle peut rester libre.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('df10d3c4-374f-46b9-a069-992fdaa6e662', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse · Ranger en zones', 'Keynapse · Ranger en zones
Ranger en zones: le bouton Zones ouvre le gestionnaire (créer, renommer, recolorer, aller à une zone). Les bulles d''une même zone partagent sa couleur et se regroupent doucement. Une bulle peut rester libre.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8bc906b4-c84c-4f97-8fef-f07e7aab4fa6', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse · Tisser des liens', '{"statement":"Tisser des liens: dans le panneau d''une bulle, section « Liens » → « Relier à… ». Cliquez une bulle reliée pour que la caméra y vole. Le « × » à droite d''un lien le retire."}', 'Keynapse · Tisser des liens
Tisser des liens: dans le panneau d''une bulle, section « Liens » → « Relier à… ». Cliquez une bulle reliée pour que la caméra y vole. Le « × » à droite d''un lien le retire.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8bc906b4-c84c-4f97-8fef-f07e7aab4fa6', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse · Tisser des liens', 'Keynapse · Tisser des liens
