INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('b5db8ce5-470e-4bfc-b694-6a18dfd3280d', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse · Captures', '{"statement":"Captures: ajoutez une photo, un croquis dessiné, ou un mémo vocal. La note vocale est transcrite et l''IA vous propose des tâches et des rappels à cocher avant de les créer. Tout est consultable en plein écran."}', 'Keynapse · Captures
Captures: ajoutez une photo, un croquis dessiné, ou un mémo vocal. La note vocale est transcrite et l''IA vous propose des tâches et des rappels à cocher avant de les créer. Tout est consultable en plein écran.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('b5db8ce5-470e-4bfc-b694-6a18dfd3280d', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse · Captures', 'Keynapse · Captures
Captures: ajoutez une photo, un croquis dessiné, ou un mémo vocal. La note vocale est transcrite et l''IA vous propose des tâches et des rappels à cocher avant de les créer. Tout est consultable en plein écran.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('84e2ef15-190d-404b-99a0-d95240617586', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse · Rappels', '{"statement":"Rappels: posez une date, une heure (à la molette) et une répétition. Tant que Keynapse est ouvert, un bandeau et une sonnerie vous préviennent à l''échéance; sur ordinateur, une notification système peut aussi s''afficher."}', 'Keynapse · Rappels
Rappels: posez une date, une heure (à la molette) et une répétition. Tant que Keynapse est ouvert, un bandeau et une sonnerie vous préviennent à l''échéance; sur ordinateur, une notification système peut aussi s''afficher.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('84e2ef15-190d-404b-99a0-d95240617586', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse · Rappels', 'Keynapse · Rappels
Rappels: posez une date, une heure (à la molette) et une répétition. Tant que Keynapse est ouvert, un bandeau et une sonnerie vous préviennent à l''échéance; sur ordinateur, une notification système peut aussi s''afficher.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('fb68f786-f872-4e02-bcb2-41ef80943e47', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Où sont stockées mes notes ? Sont-elles privées ?', '{"question":"Où sont stockées mes notes ? Sont-elles privées ?","answer":"Tout est rangé dans votre espace Keystone (base de données et stockage de fichiers), rattaché à votre compte. Vos bulles, photos, croquis et mémos vocaux ne sont jamais publics ni partagés: Keynapse est un outil personnel."}', 'Où sont stockées mes notes ? Sont-elles privées ?
Où sont stockées mes notes ? Sont-elles privées ?
Tout est rangé dans votre espace Keystone (base de données et stockage de fichiers), rattaché à votre compte. Vos bulles, photos, croquis et mémos vocaux ne sont jamais publics ni partagés: Keynapse est un outil personnel.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('fb68f786-f872-4e02-bcb2-41ef80943e47', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Où sont stockées mes notes ? Sont-elles privées ?', 'Où sont stockées mes notes ? Sont-elles privées ?
Où sont stockées mes notes ? Sont-elles privées ?
Tout est rangé dans votre espace Keystone (base de données et stockage de fichiers), rattaché à votre compte. Vos bulles, photos, croquis et mémos vocaux ne sont jamais publics ni partagés: Keynapse est un outil personnel.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('2da86cf2-27bb-44c6-b507-3a56c0af9267', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'La note vocale consomme-t-elle des conversations ?', '{"question":"La note vocale consomme-t-elle des conversations ?","answer":"Oui: la transcription du mémo puis l''analyse qui en tire des tâches et rappels comptent comme des actions IA (au compteur de conversations). L''enregistrement audio, lui, est toujours conservé même si l''IA n''est pas disponible — vous ne perdez jamais votre mémo."}', 'La note vocale consomme-t-elle des conversations ?
La note vocale consomme-t-elle des conversations ?
Oui: la transcription du mémo puis l''analyse qui en tire des tâches et rappels comptent comme des actions IA (au compteur de conversations). L''enregistrement audio, lui, est toujours conservé même si l''IA n''est pas disponible — vous ne perdez jamais votre mémo.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('2da86cf2-27bb-44c6-b507-3a56c0af9267', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'La note vocale consomme-t-elle des conversations ?', 'La note vocale consomme-t-elle des conversations ?
La note vocale consomme-t-elle des conversations ?
Oui: la transcription du mémo puis l''analyse qui en tire des tâches et rappels comptent comme des actions IA (au compteur de conversations). L''enregistrement audio, lui, est toujours conservé même si l''IA n''est pas disponible — vous ne perdez jamais votre mémo.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('5a91d3cb-71f2-4b7c-acb3-b281eb8cf623', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Serai-je prévenu d''un rappel si Keynapse est fermé ?', '{"question":"Serai-je prévenu d''un rappel si Keynapse est fermé ?","answer":"Les notifications sont locales: elles se déclenchent quand le pad est ouvert (bandeau dans l''app + sonnerie, et notification système sur ordinateur si vous l''avez autorisée). Sur iPhone dans Safari, seul le bandeau s''affiche. Les rappels par notification même app fermée viendront plus tard."}', 'Serai-je prévenu d''un rappel si Keynapse est fermé ?
Serai-je prévenu d''un rappel si Keynapse est fermé ?
Les notifications sont locales: elles se déclenchent quand le pad est ouvert (bandeau dans l''app + sonnerie, et notification système sur ordinateur si vous l''avez autorisée). Sur iPhone dans Safari, seul le bandeau s''affiche. Les rappels par notification même app fermée viendront plus tard.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('5a91d3cb-71f2-4b7c-acb3-b281eb8cf623', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Serai-je prévenu d''un rappel si Keynapse est fermé ?', 'Serai-je prévenu d''un rappel si Keynapse est fermé ?
Serai-je prévenu d''un rappel si Keynapse est fermé ?
Les notifications sont locales: elles se déclenchent quand le pad est ouvert (bandeau dans l''app + sonnerie, et notification système sur ordinateur si vous l''avez autorisée). Sur iPhone dans Safari, seul le bandeau s''affiche. Les rappels par notification même app fermée viendront plus tard.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('3bce52b5-4f55-4aa2-9bdb-0288e4c9d7d5', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Comment supprimer un lien, une capture ou un rappel ?', '{"question":"Comment supprimer un lien, une capture ou un rappel ?","answer":"Ouvrez la bulle concernée: chaque lien, chaque vignette de capture et chaque rappel a un « × » pour le retirer. Pour supprimer une bulle entière, utilisez « Supprimer cette bulle » en bas de son panneau (avec confirmation)."}', 'Comment supprimer un lien, une capture ou un rappel ?
Comment supprimer un lien, une capture ou un rappel ?
Ouvrez la bulle concernée: chaque lien, chaque vignette de capture et chaque rappel a un « × » pour le retirer. Pour supprimer une bulle entière, utilisez « Supprimer cette bulle » en bas de son panneau (avec confirmation).', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('3bce52b5-4f55-4aa2-9bdb-0288e4c9d7d5', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Comment supprimer un lien, une capture ou un rappel ?', 'Comment supprimer un lien, une capture ou un rappel ?
Comment supprimer un lien, une capture ou un rappel ?
Ouvrez la bulle concernée: chaque lien, chaque vignette de capture et chaque rappel a un « × » pour le retirer. Pour supprimer une bulle entière, utilisez « Supprimer cette bulle » en bas de son panneau (avec confirmation).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('1a0ab0a3-9d69-45cc-ae48-3b935a179ef5', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'L''animation des bulles me gêne (mal de mer).', '{"question":"L''animation des bulles me gêne (mal de mer).","answer":"Le bouton en forme d''onde, en haut à droite, fige la respiration des bulles et la souplesse des liens: la carte se stabilise, tout reste cliquable et déplaçable. Votre choix est mémorisé, et Keynapse respecte aussi le réglage « réduire les animations » de votre appareil."}', 'L''animation des bulles me gêne (mal de mer).
L''animation des bulles me gêne (mal de mer).
Le bouton en forme d''onde, en haut à droite, fige la respiration des bulles et la souplesse des liens: la carte se stabilise, tout reste cliquable et déplaçable. Votre choix est mémorisé, et Keynapse respecte aussi le réglage « réduire les animations » de votre appareil.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('1a0ab0a3-9d69-45cc-ae48-3b935a179ef5', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'L''animation des bulles me gêne (mal de mer).', 'L''animation des bulles me gêne (mal de mer).
L''animation des bulles me gêne (mal de mer).
Le bouton en forme d''onde, en haut à droite, fige la respiration des bulles et la souplesse des liens: la carte se stabilise, tout reste cliquable et déplaçable. Votre choix est mémorisé, et Keynapse respecte aussi le réglage « réduire les animations » de votre appareil.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('3ca9a2ff-3657-4e0a-a69d-64da26e61347', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse — La limite des notes linéaires', '{"statement":"Dans une liste, deux idées proches mais notées à dix jours d''écart se retrouvent loin l''une de l''autre. On perd les rapprochements. On ne voit pas non plus la « forme » de l''ensemble: quels sujets prennent de l''ampleur, lesquels restent isolés. L''information est là, mais pas la vue d''ensemble."}', 'Keynapse — La limite des notes linéaires
Dans une liste, deux idées proches mais notées à dix jours d''écart se retrouvent loin l''une de l''autre. On perd les rapprochements. On ne voit pas non plus la « forme » de l''ensemble: quels sujets prennent de l''ampleur, lesquels restent isolés. L''information est là, mais pas la vue d''ensemble.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('3ca9a2ff-3657-4e0a-a69d-64da26e61347', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse — La limite des notes linéaires', 'Keynapse — La limite des notes linéaires
Dans une liste, deux idées proches mais notées à dix jours d''écart se retrouvent loin l''une de l''autre. On perd les rapprochements. On ne voit pas non plus la « forme » de l''ensemble: quels sujets prennent de l''ampleur, lesquels restent isolés. L''information est là, mais pas la vue d''ensemble.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('68554806-633c-40ce-985f-b27ac82bd2e4', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse — Ce qu''apporte un espace visuel', '{"statement":"Le spatial: poser chaque idée à un endroit, la déplacer, la rapprocher d''une autre. La mémoire retient mieux ce qui a une position. Les regroupements: rassembler par zones de couleur ce qui va ensemble, sans imposer de hiérarchie rigide. Les liens: relier deux idées éloignées d''un trait, et naviguer de l''une à l''autre — c''est là que naissent les connexions inattendues. Le zoom: voir les grands ensembles de loin, le détail de près, comme une carte."}', 'Keynapse — Ce qu''apporte un espace visuel
Le spatial: poser chaque idée à un endroit, la déplacer, la rapprocher d''une autre. La mémoire retient mieux ce qui a une position. Les regroupements: rassembler par zones de couleur ce qui va ensemble, sans imposer de hiérarchie rigide. Les liens: relier deux idées éloignées d''un trait, et naviguer de l''une à l''autre — c''est là que naissent les connexions inattendues. Le zoom: voir les grands ensembles de loin, le détail de près, comme une carte.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('68554806-633c-40ce-985f-b27ac82bd2e4', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse — Ce qu''apporte un espace visuel', 'Keynapse — Ce qu''apporte un espace visuel
Le spatial: poser chaque idée à un endroit, la déplacer, la rapprocher d''une autre. La mémoire retient mieux ce qui a une position. Les regroupements: rassembler par zones de couleur ce qui va ensemble, sans imposer de hiérarchie rigide. Les liens: relier deux idées éloignées d''un trait, et naviguer de l''une à l''autre — c''est là que naissent les connexions inattendues. Le zoom: voir les grands ensembles de loin, le détail de près, comme une carte.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('68e39429-7352-43c9-bb18-f9fb6f33ce2c', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Keynapse — Linéaire ou visuel: pas l''un contre l''autre', '{"statement":"Une liste reste idéale pour une tâche à cocher ou un compte rendu. Le visuel prend le dessus dès qu''il s''agit d''explorer, de structurer un projet flou, de faire émerger un plan. Les deux se complètent. Keynapse est cet espace visuel: des bulles de notes sur un canevas infini, regroupées en zones et reliées entre elles, qui restent entièrement privées."}', 'Keynapse — Linéaire ou visuel: pas l''un contre l''autre
Une liste reste idéale pour une tâche à cocher ou un compte rendu. Le visuel prend le dessus dès qu''il s''agit d''explorer, de structurer un projet flou, de faire émerger un plan. Les deux se complètent. Keynapse est cet espace visuel: des bulles de notes sur un canevas infini, regroupées en zones et reliées entre elles, qui restent entièrement privées.', 'validated', 'import', 'apps:keynapse', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('68e39429-7352-43c9-bb18-f9fb6f33ce2c', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Keynapse — Linéaire ou visuel: pas l''un contre l''autre', 'Keynapse — Linéaire ou visuel: pas l''un contre l''autre
Une liste reste idéale pour une tâche à cocher ou un compte rendu. Le visuel prend le dessus dès qu''il s''agit d''explorer, de structurer un projet flou, de faire émerger un plan. Les deux se complètent. Keynapse est cet espace visuel: des bulles de notes sur un canevas infini, regroupées en zones et reliées entre elles, qui restent entièrement privées.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('547c9e04-ebb1-4c4f-b6ab-e38574e7f9d5', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Missive, en une phrase', '{"term":"Missive","definition":"Missive transmet un secret — mot de passe, code, information sensible — qui se lit une seule fois puis s''autodétruit. Le contenu est chiffré sur votre appareil: même nous ne pouvons pas le lire. Vous partagez un lien (ou un QR, ou une puce NFC) et, par un autre canal, un code de déverrouillage. Au-delà de quelques essais ratés, la missive meurt définitivement."}', 'Missive, en une phrase
Missive
Missive transmet un secret — mot de passe, code, information sensible — qui se lit une seule fois puis s''autodétruit. Le contenu est chiffré sur votre appareil: même nous ne pouvons pas le lire. Vous partagez un lien (ou un QR, ou une puce NFC) et, par un autre canal, un code de déverrouillage. Au-delà de quelques essais ratés, la missive meurt définitivement.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('547c9e04-ebb1-4c4f-b6ab-e38574e7f9d5', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive, en une phrase', 'Missive, en une phrase
Missive
Missive transmet un secret — mot de passe, code, information sensible — qui se lit une seule fois puis s''autodétruit. Le contenu est chiffré sur votre appareil: même nous ne pouvons pas le lire. Vous partagez un lien (ou un QR, ou une puce NFC) et, par un autre canal, un code de déverrouillage. Au-delà de quelques essais ratés, la missive meurt définitivement.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('5154c8d0-1d72-4929-a225-2e1bd29d8928', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive · Créer une missive', '{"statement":"Créer une missive: collez le secret, choisissez le nombre d''essais et l''expiration, puis « Sceller ». Tout est chiffré sur votre appareil — le serveur ne voit jamais le contenu en clair."}', 'Missive · Créer une missive
Créer une missive: collez le secret, choisissez le nombre d''essais et l''expiration, puis « Sceller ». Tout est chiffré sur votre appareil — le serveur ne voit jamais le contenu en clair.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('5154c8d0-1d72-4929-a225-2e1bd29d8928', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive · Créer une missive', 'Missive · Créer une missive
Créer une missive: collez le secret, choisissez le nombre d''essais et l''expiration, puis « Sceller ». Tout est chiffré sur votre appareil — le serveur ne voit jamais le contenu en clair.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('21b3b53d-8ea5-4c37-9a91-2042e530c5ad', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive · Deux éléments à transmettre, par deux ca', '{"statement":"Deux éléments à transmettre, par deux canaux différents: le lien (ou le QR / la puce NFC) d''un côté, et le code de déverrouillage de l''autre. Deux formats de code au choix: « Sécurité maximale » (long, à copier-coller) ou « Facile à dicter » (3 mots + un nombre, parfait au téléphone). Le code n''est affiché qu''une fois et n''est pas récupérable — notez-le ou copiez-le avant de fermer."}', 'Missive · Deux éléments à transmettre, par deux ca
Deux éléments à transmettre, par deux canaux différents: le lien (ou le QR / la puce NFC) d''un côté, et le code de déverrouillage de l''autre. Deux formats de code au choix: « Sécurité maximale » (long, à copier-coller) ou « Facile à dicter » (3 mots + un nombre, parfait au téléphone). Le code n''est affiché qu''une fois et n''est pas récupérable — notez-le ou copiez-le avant de fermer.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('21b3b53d-8ea5-4c37-9a91-2042e530c5ad', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive · Deux éléments à transmettre, par deux ca', 'Missive · Deux éléments à transmettre, par deux ca
Deux éléments à transmettre, par deux canaux différents: le lien (ou le QR / la puce NFC) d''un côté, et le code de déverrouillage de l''autre. Deux formats de code au choix: « Sécurité maximale » (long, à copier-coller) ou « Facile à dicter » (3 mots + un nombre, parfait au téléphone). Le code n''est affiché qu''une fois et n''est pas récupérable — notez-le ou copiez-le avant de fermer.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('d0b9f6a2-633e-4397-a4b9-36711ef247bc', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive · Lecture unique', '{"statement":"Lecture unique: le destinataire ouvre le lien, saisit le code, lit le message — puis la missive se referme. Vous êtes averti quand elle a été ouverte (dans la barre d''ambiance du tableau de bord)."}', 'Missive · Lecture unique
Lecture unique: le destinataire ouvre le lien, saisit le code, lit le message — puis la missive se referme. Vous êtes averti quand elle a été ouverte (dans la barre d''ambiance du tableau de bord).', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('d0b9f6a2-633e-4397-a4b9-36711ef247bc', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive · Lecture unique', 'Missive · Lecture unique
Lecture unique: le destinataire ouvre le lien, saisit le code, lit le message — puis la missive se referme. Vous êtes averti quand elle a été ouverte (dans la barre d''ambiance du tableau de bord).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('6e4677d3-a39d-448e-b7b1-6c67e3c0e833', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive · Autodestruction', '{"statement":"Autodestruction: après le nombre d''essais choisi (3 par défaut, ou 1 pour un usage strict), la missive meurt — plus personne ne peut l''ouvrir, même avec le bon code. Si une missive meurt sur des essais ratés sans avoir été lue, une alerte « possible interception » s''affiche."}', 'Missive · Autodestruction
Autodestruction: après le nombre d''essais choisi (3 par défaut, ou 1 pour un usage strict), la missive meurt — plus personne ne peut l''ouvrir, même avec le bon code. Si une missive meurt sur des essais ratés sans avoir été lue, une alerte « possible interception » s''affiche.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('6e4677d3-a39d-448e-b7b1-6c67e3c0e833', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive · Autodestruction', 'Missive · Autodestruction
Autodestruction: après le nombre d''essais choisi (3 par défaut, ou 1 pour un usage strict), la missive meurt — plus personne ne peut l''ouvrir, même avec le bon code. Si une missive meurt sur des essais ratés sans avoir été lue, une alerte « possible interception » s''affiche.');
