INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('51ceaa8c-c302-45dc-9067-a88711afe8ee', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive · NFC', '{"statement":"NFC: l''écriture d''une puce demande un téléphone Android avec Chrome. Sur iPhone et ordinateur, utilisez le QR ou le lien (toujours proposés). La lecture au contact fonctionne sur iPhone récent comme sur Android."}', 'Missive · NFC
NFC: l''écriture d''une puce demande un téléphone Android avec Chrome. Sur iPhone et ordinateur, utilisez le QR ou le lien (toujours proposés). La lecture au contact fonctionne sur iPhone récent comme sur Android.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('51ceaa8c-c302-45dc-9067-a88711afe8ee', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive · NFC', 'Missive · NFC
NFC: l''écriture d''une puce demande un téléphone Android avec Chrome. Sur iPhone et ordinateur, utilisez le QR ou le lien (toujours proposés). La lecture au contact fonctionne sur iPhone récent comme sur Android.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('d4f85387-d0aa-457e-a871-cd624f7b525f', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Est-ce vraiment sécurisé ? Pouvez-vous lire mes secrets ?', '{"question":"Est-ce vraiment sécurisé ? Pouvez-vous lire mes secrets ?","answer":"Non, nous ne pouvons pas les lire. Le secret est chiffré de bout en bout sur votre appareil avec une clé dérivée du code de déverrouillage, que nous ne voyons jamais. Nos serveurs ne stockent que du contenu chiffré, illisible sans le code. La seule limite honnête: cette page web est servie par notre serveur, donc une sécurité de niveau « secret d''État » supposerait de ne pas nous faire confiance pour le code de la page — pour tout usage courant (mots de passe, codes, infos sensibles), c''est solide."}', 'Est-ce vraiment sécurisé ? Pouvez-vous lire mes secrets ?
Est-ce vraiment sécurisé ? Pouvez-vous lire mes secrets ?
Non, nous ne pouvons pas les lire. Le secret est chiffré de bout en bout sur votre appareil avec une clé dérivée du code de déverrouillage, que nous ne voyons jamais. Nos serveurs ne stockent que du contenu chiffré, illisible sans le code. La seule limite honnête: cette page web est servie par notre serveur, donc une sécurité de niveau « secret d''État » supposerait de ne pas nous faire confiance pour le code de la page — pour tout usage courant (mots de passe, codes, infos sensibles), c''est solide.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('d4f85387-d0aa-457e-a871-cd624f7b525f', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Est-ce vraiment sécurisé ? Pouvez-vous lire mes secrets ?', 'Est-ce vraiment sécurisé ? Pouvez-vous lire mes secrets ?
Est-ce vraiment sécurisé ? Pouvez-vous lire mes secrets ?
Non, nous ne pouvons pas les lire. Le secret est chiffré de bout en bout sur votre appareil avec une clé dérivée du code de déverrouillage, que nous ne voyons jamais. Nos serveurs ne stockent que du contenu chiffré, illisible sans le code. La seule limite honnête: cette page web est servie par notre serveur, donc une sécurité de niveau « secret d''État » supposerait de ne pas nous faire confiance pour le code de la page — pour tout usage courant (mots de passe, codes, infos sensibles), c''est solide.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('29d9e8bc-9cd7-4ea9-88dc-e72ea7c4719b', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Que se passe-t-il si je perds le code de déverrouillage ?', '{"question":"Que se passe-t-il si je perds le code de déverrouillage ?","answer":"Le secret est définitivement perdu. C''est le prix de la confidentialité réelle: personne, pas même nous, ne peut le récupérer. Transmettez le code au destinataire dès la création, par un canal différent du lien."}', 'Que se passe-t-il si je perds le code de déverrouillage ?
Que se passe-t-il si je perds le code de déverrouillage ?
Le secret est définitivement perdu. C''est le prix de la confidentialité réelle: personne, pas même nous, ne peut le récupérer. Transmettez le code au destinataire dès la création, par un canal différent du lien.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('29d9e8bc-9cd7-4ea9-88dc-e72ea7c4719b', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Que se passe-t-il si je perds le code de déverrouillage ?', 'Que se passe-t-il si je perds le code de déverrouillage ?
Que se passe-t-il si je perds le code de déverrouillage ?
Le secret est définitivement perdu. C''est le prix de la confidentialité réelle: personne, pas même nous, ne peut le récupérer. Transmettez le code au destinataire dès la création, par un canal différent du lien.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('a4d71a2d-5801-4b51-98b4-8d3f120b9459', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Par quel canal transmettre le code ?', '{"question":"Par quel canal transmettre le code ?","answer":"Par un canal différent de celui du lien, et de préférence pas par SMS seul (vulnérable au détournement de carte SIM). De vive voix, par un autre messager, ou en personne: l''idée est qu''une seule interception ne donne jamais à la fois le lien et le code."}', 'Par quel canal transmettre le code ?
Par quel canal transmettre le code ?
Par un canal différent de celui du lien, et de préférence pas par SMS seul (vulnérable au détournement de carte SIM). De vive voix, par un autre messager, ou en personne: l''idée est qu''une seule interception ne donne jamais à la fois le lien et le code.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('a4d71a2d-5801-4b51-98b4-8d3f120b9459', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Par quel canal transmettre le code ?', 'Par quel canal transmettre le code ?
Par quel canal transmettre le code ?
Par un canal différent de celui du lien, et de préférence pas par SMS seul (vulnérable au détournement de carte SIM). De vive voix, par un autre messager, ou en personne: l''idée est qu''une seule interception ne donne jamais à la fois le lien et le code.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('6606b712-c886-40cf-9dfb-749cd3680ee4', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Que peut-on envoyer par Missive — et qu''est-ce qu''il vaut mieux éviter ?', '{"question":"Que peut-on envoyer par Missive — et qu''est-ce qu''il vaut mieux éviter ?","answer":"Missive est faite pour les secrets opérationnels: mots de passe, codes d''accès, coordonnées bancaires à saisir, clés API, instructions confidentielles ponctuelles. À l''inverse, évitez d''y faire passer SEUL tout ce qui pourrait devoir être prouvé plus tard: engagement contractuel, échange RH sensible, instruction qui engage votre responsabilité. Une missive détruite ne peut pas servir de preuve — c''est voulu. Pour ces sujets, doublez par un canal archivé (email). Règle simple à adopter en équipe: « Missive = transmettre un secret, jamais archiver une décision. Tout ce qui a valeur de preuve passe aussi par l''email. »"}', 'Que peut-on envoyer par Missive — et qu''est-ce qu''il vaut mieux éviter ?
Que peut-on envoyer par Missive — et qu''est-ce qu''il vaut mieux éviter ?
Missive est faite pour les secrets opérationnels: mots de passe, codes d''accès, coordonnées bancaires à saisir, clés API, instructions confidentielles ponctuelles. À l''inverse, évitez d''y faire passer SEUL tout ce qui pourrait devoir être prouvé plus tard: engagement contractuel, échange RH sensible, instruction qui engage votre responsabilité. Une missive détruite ne peut pas servir de preuve — c''est voulu. Pour ces sujets, doublez par un canal archivé (email). Règle simple à adopter en équipe: « Missive = transmettre un secret, jamais archiver une décision. Tout ce qui a valeur de preuve passe aussi par l''email. »', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('6606b712-c886-40cf-9dfb-749cd3680ee4', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Que peut-on envoyer par Missive — et qu''est-ce qu''il vaut mieux éviter ?', 'Que peut-on envoyer par Missive — et qu''est-ce qu''il vaut mieux éviter ?
Que peut-on envoyer par Missive — et qu''est-ce qu''il vaut mieux éviter ?
Missive est faite pour les secrets opérationnels: mots de passe, codes d''accès, coordonnées bancaires à saisir, clés API, instructions confidentielles ponctuelles. À l''inverse, évitez d''y faire passer SEUL tout ce qui pourrait devoir être prouvé plus tard: engagement contractuel, échange RH sensible, instruction qui engage votre responsabilité. Une missive détruite ne peut pas servir de preuve — c''est voulu. Pour ces sujets, doublez par un canal archivé (email). Règle simple à adopter en équipe: « Missive = transmettre un secret, jamais archiver une décision. Tout ce qui a valeur de preuve passe aussi par l''email. »');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('85a8edc6-5e52-492e-b616-62cdfee8a58b', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Missive est-elle compatible RGPD ? Que noter dans mon registre des traitements ?', '{"question":"Missive est-elle compatible RGPD ? Que noter dans mon registre des traitements ?","answer":"Oui — et plutôt deux fois qu''une: la minimisation et la limitation de conservation que le RGPD recommande sont ici garanties par construction (contenu chiffré illisible par l''éditeur, autodestruction, traces techniques purgées sous 24 h). Si vous tenez un registre des traitements, vous pouvez y recopier ceci: « Transmission ponctuelle d''informations sensibles via messagerie éphémère chiffrée de bout en bout (Missive, Keystone OS). Contenu illisible par l''éditeur; autodestruction après lecture unique, expiration ou épuisement des essais; métadonnées techniques purgées sous 24 heures. Ce canal n''est pas utilisé pour des données soumises à une obligation légale de conservation. » Une donnée déjà autodétruite ne peut plus être fournie lors d''une demande d''accès: c''est conforme, du moment que c''est documenté et que le canal n''est pas utilisé pour ce qui doit être conservé."}', 'Missive est-elle compatible RGPD ? Que noter dans mon registre des traitements ?
Missive est-elle compatible RGPD ? Que noter dans mon registre des traitements ?
Oui — et plutôt deux fois qu''une: la minimisation et la limitation de conservation que le RGPD recommande sont ici garanties par construction (contenu chiffré illisible par l''éditeur, autodestruction, traces techniques purgées sous 24 h). Si vous tenez un registre des traitements, vous pouvez y recopier ceci: « Transmission ponctuelle d''informations sensibles via messagerie éphémère chiffrée de bout en bout (Missive, Keystone OS). Contenu illisible par l''éditeur; autodestruction après lecture unique, expiration ou épuisement des essais; métadonnées techniques purgées sous 24 heures. Ce canal n''est pas utilisé pour des données soumises à une obligation légale de conservation. » Une donnée déjà autodétruite ne peut plus être fournie lors d''une demande d''accès: c''est conforme, du moment que c''est documenté et que le canal n''est pas utilisé pour ce qui doit être conservé.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('85a8edc6-5e52-492e-b616-62cdfee8a58b', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive est-elle compatible RGPD ? Que noter dans mon registre des traitements ?', 'Missive est-elle compatible RGPD ? Que noter dans mon registre des traitements ?
Missive est-elle compatible RGPD ? Que noter dans mon registre des traitements ?
Oui — et plutôt deux fois qu''une: la minimisation et la limitation de conservation que le RGPD recommande sont ici garanties par construction (contenu chiffré illisible par l''éditeur, autodestruction, traces techniques purgées sous 24 h). Si vous tenez un registre des traitements, vous pouvez y recopier ceci: « Transmission ponctuelle d''informations sensibles via messagerie éphémère chiffrée de bout en bout (Missive, Keystone OS). Contenu illisible par l''éditeur; autodestruction après lecture unique, expiration ou épuisement des essais; métadonnées techniques purgées sous 24 heures. Ce canal n''est pas utilisé pour des données soumises à une obligation légale de conservation. » Une donnée déjà autodétruite ne peut plus être fournie lors d''une demande d''accès: c''est conforme, du moment que c''est documenté et que le canal n''est pas utilisé pour ce qui doit être conservé.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('90471127-4818-4d05-acd4-17de673b3342', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', '« Lu une fois »: et si quelqu''un filme l''écran ?', '{"question":"« Lu une fois »: et si quelqu''un filme l''écran ?","answer":"On garantit qu''on ne peut plus accéder au message par ce lien après lecture — pas qu''il n''a pas été capturé pendant qu''il s''affichait. Missive protège contre l''interception du lien, pas contre un destinataire qui photographie son propre écran. C''est de l''éphémère sécurisé, pas de l''anti-capture."}', '« Lu une fois »: et si quelqu''un filme l''écran ?
« Lu une fois »: et si quelqu''un filme l''écran ?
On garantit qu''on ne peut plus accéder au message par ce lien après lecture — pas qu''il n''a pas été capturé pendant qu''il s''affichait. Missive protège contre l''interception du lien, pas contre un destinataire qui photographie son propre écran. C''est de l''éphémère sécurisé, pas de l''anti-capture.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('90471127-4818-4d05-acd4-17de673b3342', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', '« Lu une fois »: et si quelqu''un filme l''écran ?', '« Lu une fois »: et si quelqu''un filme l''écran ?
« Lu une fois »: et si quelqu''un filme l''écran ?
On garantit qu''on ne peut plus accéder au message par ce lien après lecture — pas qu''il n''a pas été capturé pendant qu''il s''affichait. Missive protège contre l''interception du lien, pas contre un destinataire qui photographie son propre écran. C''est de l''éphémère sécurisé, pas de l''anti-capture.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('473ad09d-600c-4d90-ba1a-d63d05da87d7', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Missive consomme-t-elle des conversations ?', '{"question":"Missive consomme-t-elle des conversations ?","answer":"Non. Missive n''utilise aucune intelligence artificielle — uniquement du chiffrement. Zéro conversation consommée, jamais."}', 'Missive consomme-t-elle des conversations ?
Missive consomme-t-elle des conversations ?
Non. Missive n''utilise aucune intelligence artificielle — uniquement du chiffrement. Zéro conversation consommée, jamais.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('473ad09d-600c-4d90-ba1a-d63d05da87d7', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive consomme-t-elle des conversations ?', 'Missive consomme-t-elle des conversations ?
Missive consomme-t-elle des conversations ?
Non. Missive n''utilise aucune intelligence artificielle — uniquement du chiffrement. Zéro conversation consommée, jamais.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('7ae0a8eb-5fbb-4990-9697-7c5bec0f866a', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive — Les bons réflexes', '{"statement":"Chiffrement de bout en bout: le secret est illisible, y compris pour le service qui le transmet. Lecture unique: le message s''autodétruit après avoir été lu une fois. Deux canaux séparés: le lien d''un côté, le code de déverrouillage de l''autre (de vive voix, autre messagerie). Une seule interception ne suffit alors jamais. Une expiration: si le destinataire ne lit pas à temps, le secret meurt."}', 'Missive — Les bons réflexes
Chiffrement de bout en bout: le secret est illisible, y compris pour le service qui le transmet. Lecture unique: le message s''autodétruit après avoir été lu une fois. Deux canaux séparés: le lien d''un côté, le code de déverrouillage de l''autre (de vive voix, autre messagerie). Une seule interception ne suffit alors jamais. Une expiration: si le destinataire ne lit pas à temps, le secret meurt.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('7ae0a8eb-5fbb-4990-9697-7c5bec0f866a', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive — Les bons réflexes', 'Missive — Les bons réflexes
Chiffrement de bout en bout: le secret est illisible, y compris pour le service qui le transmet. Lecture unique: le message s''autodétruit après avoir été lu une fois. Deux canaux séparés: le lien d''un côté, le code de déverrouillage de l''autre (de vive voix, autre messagerie). Une seule interception ne suffit alors jamais. Une expiration: si le destinataire ne lit pas à temps, le secret meurt.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('017cdca6-62ac-4ca3-a1b9-b3e15239829a', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive — Ce que « sécurisé » veut dire (et ne veut pas dire)', '{"statement":"Un bon outil garantit qu''on ne peut plus accéder au message après lecture, et qu''il était illisible en transit. Il ne protège pas contre un destinataire qui photographie son propre écran: c''est de l''éphémère sécurisé, pas de l''anti-capture. Pour un mot de passe, un code ou une information sensible, c''est largement suffisant. Missive applique exactement ces principes: chiffré sur votre appareil, lu une seule fois, lien et code par deux canaux, expiration et autodestruction."}', 'Missive — Ce que « sécurisé » veut dire (et ne veut pas dire)
Un bon outil garantit qu''on ne peut plus accéder au message après lecture, et qu''il était illisible en transit. Il ne protège pas contre un destinataire qui photographie son propre écran: c''est de l''éphémère sécurisé, pas de l''anti-capture. Pour un mot de passe, un code ou une information sensible, c''est largement suffisant. Missive applique exactement ces principes: chiffré sur votre appareil, lu une seule fois, lien et code par deux canaux, expiration et autodestruction.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('017cdca6-62ac-4ca3-a1b9-b3e15239829a', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive — Ce que « sécurisé » veut dire (et ne veut pas dire)', 'Missive — Ce que « sécurisé » veut dire (et ne veut pas dire)
Un bon outil garantit qu''on ne peut plus accéder au message après lecture, et qu''il était illisible en transit. Il ne protège pas contre un destinataire qui photographie son propre écran: c''est de l''éphémère sécurisé, pas de l''anti-capture. Pour un mot de passe, un code ou une information sensible, c''est largement suffisant. Missive applique exactement ces principes: chiffré sur votre appareil, lu une seule fois, lien et code par deux canaux, expiration et autodestruction.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('df387a3a-ebbc-4e08-be9f-3ee6ce0d8eef', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Missive — Encadrer l''usage en entreprise', '{"statement":"Un message autodétruit ne peut pas servir de preuve — c''est sa raison d''être. La bonne pratique en équipe tient en une règle: Missive sert à transmettre un secret, jamais à archiver une décision. Engagements, échanges RH, instructions qui engagent la responsabilité: doublez-les par un canal archivé (email). Côté RGPD, l''éphémère chiffré joue pour vous — minimisation et conservation limitée sont garanties par construction — à condition de documenter ce choix dans votre registre des traitements et de réserver le canal aux données sans obligation légale de conservation."}', 'Missive — Encadrer l''usage en entreprise
Un message autodétruit ne peut pas servir de preuve — c''est sa raison d''être. La bonne pratique en équipe tient en une règle: Missive sert à transmettre un secret, jamais à archiver une décision. Engagements, échanges RH, instructions qui engagent la responsabilité: doublez-les par un canal archivé (email). Côté RGPD, l''éphémère chiffré joue pour vous — minimisation et conservation limitée sont garanties par construction — à condition de documenter ce choix dans votre registre des traitements et de réserver le canal aux données sans obligation légale de conservation.', 'validated', 'import', 'apps:missive', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('df387a3a-ebbc-4e08-be9f-3ee6ce0d8eef', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Missive — Encadrer l''usage en entreprise', 'Missive — Encadrer l''usage en entreprise
Un message autodétruit ne peut pas servir de preuve — c''est sa raison d''être. La bonne pratique en équipe tient en une règle: Missive sert à transmettre un secret, jamais à archiver une décision. Engagements, échanges RH, instructions qui engagent la responsabilité: doublez-les par un canal archivé (email). Côté RGPD, l''éphémère chiffré joue pour vous — minimisation et conservation limitée sont garanties par construction — à condition de documenter ce choix dans votre registre des traitements et de réserver le canal aux données sans obligation légale de conservation.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('0be9b9ab-00bc-435d-a2fe-4a7dffe81838', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'networK, en une phrase', '{"term":"networK","definition":"Votre réseau relationnel vivant — pas un carnet d''adresses de plus. Vous êtes au centre, et vos relations se déploient en carte mentale: des catégories libres (Clients, Fournisseurs, Partenaires…) d''où partent vos contacts. Un clic sur une catégorie la déplie; un clic sur un contact ouvre sa fiche, où vous retrouvez ses coordonnées, ses rôles, ses tags, vos notes, et un journal d''activité qui raconte votre relation. Et depuis chaque fiche, vous continuez votre travail sans ressaisir: « Continuer avec… » ouvre une Missive, un Brief ou votre Smart Agent, déjà mis en contexte. Tout est à vous, rien n''est publié."}', 'networK, en une phrase
networK
Votre réseau relationnel vivant — pas un carnet d''adresses de plus. Vous êtes au centre, et vos relations se déploient en carte mentale: des catégories libres (Clients, Fournisseurs, Partenaires…) d''où partent vos contacts. Un clic sur une catégorie la déplie; un clic sur un contact ouvre sa fiche, où vous retrouvez ses coordonnées, ses rôles, ses tags, vos notes, et un journal d''activité qui raconte votre relation. Et depuis chaque fiche, vous continuez votre travail sans ressaisir: « Continuer avec… » ouvre une Missive, un Brief ou votre Smart Agent, déjà mis en contexte. Tout est à vous, rien n''est publié.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('0be9b9ab-00bc-435d-a2fe-4a7dffe81838', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'networK, en une phrase', 'networK, en une phrase
networK
Votre réseau relationnel vivant — pas un carnet d''adresses de plus. Vous êtes au centre, et vos relations se déploient en carte mentale: des catégories libres (Clients, Fournisseurs, Partenaires…) d''où partent vos contacts. Un clic sur une catégorie la déplie; un clic sur un contact ouvre sa fiche, où vous retrouvez ses coordonnées, ses rôles, ses tags, vos notes, et un journal d''activité qui raconte votre relation. Et depuis chaque fiche, vous continuez votre travail sans ressaisir: « Continuer avec… » ouvre une Missive, un Brief ou votre Smart Agent, déjà mis en contexte. Tout est à vous, rien n''est publié.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('e57a0ba7-876b-4451-92fe-a4614996f002', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'networK · Ajouter', '{"statement":"Ajouter: le bouton « + Ajouter » crée une personne, une entreprise, un établissement, un groupe ou une nouvelle catégorie. Le « + » sur une catégorie ajoute directement un contact à l''intérieur."}', 'networK · Ajouter
Ajouter: le bouton « + Ajouter » crée une personne, une entreprise, un établissement, un groupe ou une nouvelle catégorie. Le « + » sur une catégorie ajoute directement un contact à l''intérieur.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('e57a0ba7-876b-4451-92fe-a4614996f002', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'networK · Ajouter', 'networK · Ajouter
