INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('ac6f6302-a5d2-4681-b8d9-267ffbae6ccf', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'networK · Naviguer', '{"statement":"Naviguer: cliquez une catégorie pour voir ses contacts. Sur ordinateur ils se déploient à droite; sur mobile, le réseau glisse vers eux — touchez la catégorie à nouveau pour revenir. Glissez le fond pour vous déplacer, la molette (ou les boutons +/−) pour zoomer."}', 'networK · Naviguer
Naviguer: cliquez une catégorie pour voir ses contacts. Sur ordinateur ils se déploient à droite; sur mobile, le réseau glisse vers eux — touchez la catégorie à nouveau pour revenir. Glissez le fond pour vous déplacer, la molette (ou les boutons +/−) pour zoomer.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('ac6f6302-a5d2-4681-b8d9-267ffbae6ccf', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'networK · Naviguer', 'networK · Naviguer
