INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8379a848-423a-40cd-b542-ea28bb7aa29c', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'networK · La fiche d''un contact', '{"statement":"La fiche d''un contact: cliquez un contact pour ouvrir sa fiche. Boutons d''appel, e-mail et message en un tap; onglets Résumé, Activité et Notes; rôles et tags que vous ajoutez ou retirez; et le « … » (ou la roue crantée) pour modifier ou supprimer le contact."}', 'networK · La fiche d''un contact
La fiche d''un contact: cliquez un contact pour ouvrir sa fiche. Boutons d''appel, e-mail et message en un tap; onglets Résumé, Activité et Notes; rôles et tags que vous ajoutez ou retirez; et le « … » (ou la roue crantée) pour modifier ou supprimer le contact.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8379a848-423a-40cd-b542-ea28bb7aa29c', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'networK · La fiche d''un contact', 'networK · La fiche d''un contact
La fiche d''un contact: cliquez un contact pour ouvrir sa fiche. Boutons d''appel, e-mail et message en un tap; onglets Résumé, Activité et Notes; rôles et tags que vous ajoutez ou retirez; et le « … » (ou la roue crantée) pour modifier ou supprimer le contact.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('ddad3325-d9fc-4549-9836-572c17d78888', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'networK · Le journal d''activité', '{"statement":"Le journal d''activité: dans l''onglet Activité, « Ajouter une activité » note un appel, un e-mail, un RDV, un devis… avec sa date. Les cinq plus récentes s''affichent dans le Résumé — la relation se raconte au fil du temps."}', 'networK · Le journal d''activité
Le journal d''activité: dans l''onglet Activité, « Ajouter une activité » note un appel, un e-mail, un RDV, un devis… avec sa date. Les cinq plus récentes s''affichent dans le Résumé — la relation se raconte au fil du temps.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('ddad3325-d9fc-4549-9836-572c17d78888', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'networK · Le journal d''activité', 'networK · Le journal d''activité
Le journal d''activité: dans l''onglet Activité, « Ajouter une activité » note un appel, un e-mail, un RDV, un devis… avec sa date. Les cinq plus récentes s''affichent dans le Résumé — la relation se raconte au fil du temps.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('03beec62-e1c6-4d9f-aef6-dabcedc71831', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'networK · Continuer avec…', '{"statement":"Continuer avec…: en bas de chaque fiche, les raccourcis ouvrent l''outil adapté (Missive, Brief, Smart Agent, Social) avec le contact déjà en contexte. Un outil que vous n''avez pas encore apparaît en suggestion « Découvrir », jamais imposé."}', 'networK · Continuer avec…
Continuer avec…: en bas de chaque fiche, les raccourcis ouvrent l''outil adapté (Missive, Brief, Smart Agent, Social) avec le contact déjà en contexte. Un outil que vous n''avez pas encore apparaît en suggestion « Découvrir », jamais imposé.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('03beec62-e1c6-4d9f-aef6-dabcedc71831', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'networK · Continuer avec…', 'networK · Continuer avec…
Continuer avec…: en bas de chaque fiche, les raccourcis ouvrent l''outil adapté (Missive, Brief, Smart Agent, Social) avec le contact déjà en contexte. Un outil que vous n''avez pas encore apparaît en suggestion « Découvrir », jamais imposé.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('2fd66dc2-3ddc-4b98-9edf-c21de153b777', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'networK · Ranger', '{"statement":"Ranger: le « … » d''une catégorie permet de la renommer, changer son icône, la monter/descendre ou la supprimer. Supprimer une catégorie ne supprime pas ses contacts: ils rejoignent « Sans catégorie »."}', 'networK · Ranger
Ranger: le « … » d''une catégorie permet de la renommer, changer son icône, la monter/descendre ou la supprimer. Supprimer une catégorie ne supprime pas ses contacts: ils rejoignent « Sans catégorie ».', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('2fd66dc2-3ddc-4b98-9edf-c21de153b777', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'networK · Ranger', 'networK · Ranger
Ranger: le « … » d''une catégorie permet de la renommer, changer son icône, la monter/descendre ou la supprimer. Supprimer une catégorie ne supprime pas ses contacts: ils rejoignent « Sans catégorie ».');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('d3274e25-566a-4176-afec-33e29479d35d', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Est-ce un CRM ? Mes contacts sont-ils privés ?', '{"question":"Est-ce un CRM ? Mes contacts sont-ils privés ?","answer":"networK n''est pas un CRM classique: pas de tunnel de vente ni de saisie obligatoire, juste votre réseau tel que vous le voyez. Vos contacts, notes et activités sont rangés dans votre espace Keystone, rattachés à votre compte — jamais publics ni partagés."}', 'Est-ce un CRM ? Mes contacts sont-ils privés ?
Est-ce un CRM ? Mes contacts sont-ils privés ?
networK n''est pas un CRM classique: pas de tunnel de vente ni de saisie obligatoire, juste votre réseau tel que vous le voyez. Vos contacts, notes et activités sont rangés dans votre espace Keystone, rattachés à votre compte — jamais publics ni partagés.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('d3274e25-566a-4176-afec-33e29479d35d', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Est-ce un CRM ? Mes contacts sont-ils privés ?', 'Est-ce un CRM ? Mes contacts sont-ils privés ?
Est-ce un CRM ? Mes contacts sont-ils privés ?
networK n''est pas un CRM classique: pas de tunnel de vente ni de saisie obligatoire, juste votre réseau tel que vous le voyez. Vos contacts, notes et activités sont rangés dans votre espace Keystone, rattachés à votre compte — jamais publics ni partagés.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('661caa8b-7aab-432a-8959-43d0b4bf8eb7', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Consomme-t-il des conversations ?', '{"question":"Consomme-t-il des conversations ?","answer":"Non. networK est 100 % manuel et sans intelligence artificielle: aucune action ne puise dans votre compteur de conversations. Vous ajoutez et organisez vos relations vous-même."}', 'Consomme-t-il des conversations ?
Consomme-t-il des conversations ?
Non. networK est 100 % manuel et sans intelligence artificielle: aucune action ne puise dans votre compteur de conversations. Vous ajoutez et organisez vos relations vous-même.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('661caa8b-7aab-432a-8959-43d0b4bf8eb7', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Consomme-t-il des conversations ?', 'Consomme-t-il des conversations ?
Consomme-t-il des conversations ?
Non. networK est 100 % manuel et sans intelligence artificielle: aucune action ne puise dans votre compteur de conversations. Vous ajoutez et organisez vos relations vous-même.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('a65ae77f-8480-4596-b0f1-7f06bd47158b', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Que veut dire « Continuer avec… » et « pré-rempli » ?', '{"question":"Que veut dire « Continuer avec… » et « pré-rempli » ?","answer":"Depuis une fiche, ces raccourcis ouvrent un autre outil Keystone en lui passant déjà les infos du contact. Par exemple « Publier pour ce client » ouvre Social Manager avec le message déjà amorcé à son nom — vous n''avez rien à ressaisir. Les outils que vous ne possédez pas s''affichent en suggestion, sans jamais bloquer."}', 'Que veut dire « Continuer avec… » et « pré-rempli » ?
Que veut dire « Continuer avec… » et « pré-rempli » ?
Depuis une fiche, ces raccourcis ouvrent un autre outil Keystone en lui passant déjà les infos du contact. Par exemple « Publier pour ce client » ouvre Social Manager avec le message déjà amorcé à son nom — vous n''avez rien à ressaisir. Les outils que vous ne possédez pas s''affichent en suggestion, sans jamais bloquer.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('a65ae77f-8480-4596-b0f1-7f06bd47158b', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Que veut dire « Continuer avec… » et « pré-rempli » ?', 'Que veut dire « Continuer avec… » et « pré-rempli » ?
Que veut dire « Continuer avec… » et « pré-rempli » ?
Depuis une fiche, ces raccourcis ouvrent un autre outil Keystone en lui passant déjà les infos du contact. Par exemple « Publier pour ce client » ouvre Social Manager avec le message déjà amorcé à son nom — vous n''avez rien à ressaisir. Les outils que vous ne possédez pas s''affichent en suggestion, sans jamais bloquer.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('23a452e5-851b-44ed-afab-853da16db897', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'J''ai supprimé une catégorie: où sont passés ses contacts ?', '{"question":"J''ai supprimé une catégorie: où sont passés ses contacts ?","answer":"Ils ne sont jamais supprimés avec la catégorie. Ils réapparaissent dans un panier « Sans catégorie » à la racine de votre réseau, d''où vous pouvez les rouvrir et les reclasser."}', 'J''ai supprimé une catégorie: où sont passés ses contacts ?
J''ai supprimé une catégorie: où sont passés ses contacts ?
Ils ne sont jamais supprimés avec la catégorie. Ils réapparaissent dans un panier « Sans catégorie » à la racine de votre réseau, d''où vous pouvez les rouvrir et les reclasser.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('23a452e5-851b-44ed-afab-853da16db897', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'J''ai supprimé une catégorie: où sont passés ses contacts ?', 'J''ai supprimé une catégorie: où sont passés ses contacts ?
J''ai supprimé une catégorie: où sont passés ses contacts ?
Ils ne sont jamais supprimés avec la catégorie. Ils réapparaissent dans un panier « Sans catégorie » à la racine de votre réseau, d''où vous pouvez les rouvrir et les reclasser.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('7bdb3f13-9e73-43cf-98f5-bd618f72d7b2', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Pourquoi certains contacts sont-ils cachés derrière « Voir les N autres » ?', '{"question":"Pourquoi certains contacts sont-ils cachés derrière « Voir les N autres » ?","answer":"Pour garder l''arbre lisible, une catégorie affiche ses premiers contacts puis un bouton « Voir les N autres » qui déplie le reste. La recherche en haut, elle, retrouve n''importe quel contact instantanément, même hors de sa catégorie."}', 'Pourquoi certains contacts sont-ils cachés derrière « Voir les N autres » ?
Pourquoi certains contacts sont-ils cachés derrière « Voir les N autres » ?
Pour garder l''arbre lisible, une catégorie affiche ses premiers contacts puis un bouton « Voir les N autres » qui déplie le reste. La recherche en haut, elle, retrouve n''importe quel contact instantanément, même hors de sa catégorie.', 'validated', 'import', 'apps:network', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('7bdb3f13-9e73-43cf-98f5-bd618f72d7b2', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Pourquoi certains contacts sont-ils cachés derrière « Voir les N autres » ?', 'Pourquoi certains contacts sont-ils cachés derrière « Voir les N autres » ?
Pourquoi certains contacts sont-ils cachés derrière « Voir les N autres » ?
Pour garder l''arbre lisible, une catégorie affiche ses premiers contacts puis un bouton « Voir les N autres » qui déplie le reste. La recherche en haut, elle, retrouve n''importe quel contact instantanément, même hors de sa catégorie.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('331539b5-f005-46d3-a8d1-305628a75cd0', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Sentinel, en une phrase', '{"term":"Sentinel","definition":"Votre centre de contrôle d''audit web AVEC suivi dans le temps. Sentinel surveille vos sites en continu (en ligne / hors ligne, temps de réponse), les note sur un radar à plusieurs axes (disponibilité, performance, SEO, sécurité, accessibilité, présence locale, visibilité dans les IA), et livre des correctifs clé en main: les étapes exactes pour votre plateforme et le code prêt à coller. Sa fonction phare: savoir si les IA (ChatGPT, Perplexity, Gemini) citent votre établissement quand un prospect les interroge."}', 'Sentinel, en une phrase
Sentinel
Votre centre de contrôle d''audit web AVEC suivi dans le temps. Sentinel surveille vos sites en continu (en ligne / hors ligne, temps de réponse), les note sur un radar à plusieurs axes (disponibilité, performance, SEO, sécurité, accessibilité, présence locale, visibilité dans les IA), et livre des correctifs clé en main: les étapes exactes pour votre plateforme et le code prêt à coller. Sa fonction phare: savoir si les IA (ChatGPT, Perplexity, Gemini) citent votre établissement quand un prospect les interroge.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('331539b5-f005-46d3-a8d1-305628a75cd0', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel, en une phrase', 'Sentinel, en une phrase
Sentinel
Votre centre de contrôle d''audit web AVEC suivi dans le temps. Sentinel surveille vos sites en continu (en ligne / hors ligne, temps de réponse), les note sur un radar à plusieurs axes (disponibilité, performance, SEO, sécurité, accessibilité, présence locale, visibilité dans les IA), et livre des correctifs clé en main: les étapes exactes pour votre plateforme et le code prêt à coller. Sa fonction phare: savoir si les IA (ChatGPT, Perplexity, Gemini) citent votre établissement quand un prospect les interroge.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('1ebfdbde-e350-41f2-ba08-7dd51ca8fec6', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel · Ajouter un site', '{"statement":"Ajouter un site: saisissez son adresse — Sentinel détecte la plateforme (Wix, WordPress, sur-mesure) et lance la surveillance aussitôt. Le nombre de sites dépend de votre plan (Starter 1, Pro 3, Max 5)."}', 'Sentinel · Ajouter un site
Ajouter un site: saisissez son adresse — Sentinel détecte la plateforme (Wix, WordPress, sur-mesure) et lance la surveillance aussitôt. Le nombre de sites dépend de votre plan (Starter 1, Pro 3, Max 5).', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('1ebfdbde-e350-41f2-ba08-7dd51ca8fec6', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel · Ajouter un site', 'Sentinel · Ajouter un site
Ajouter un site: saisissez son adresse — Sentinel détecte la plateforme (Wix, WordPress, sur-mesure) et lance la surveillance aussitôt. Le nombre de sites dépend de votre plan (Starter 1, Pro 3, Max 5).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('3d4e7cfa-7b4d-4a89-9b29-291b5a7bc53b', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel · Veille en direct', '{"statement":"Veille en direct: chaque carte montre l''état (en ligne / hors ligne), la disponibilité sur 24 h et une courbe des temps de réponse. « Vérifier » relance un contrôle immédiat. Activez les alertes (cloche) pour être prévenu si un site tombe ou revient."}', 'Sentinel · Veille en direct
Veille en direct: chaque carte montre l''état (en ligne / hors ligne), la disponibilité sur 24 h et une courbe des temps de réponse. « Vérifier » relance un contrôle immédiat. Activez les alertes (cloche) pour être prévenu si un site tombe ou revient.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('3d4e7cfa-7b4d-4a89-9b29-291b5a7bc53b', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel · Veille en direct', 'Sentinel · Veille en direct
Veille en direct: chaque carte montre l''état (en ligne / hors ligne), la disponibilité sur 24 h et une courbe des temps de réponse. « Vérifier » relance un contrôle immédiat. Activez les alertes (cloche) pour être prévenu si un site tombe ou revient.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('928b515c-161f-40a0-ac41-2fcaa39f409c', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel · Auditer', '{"statement":"Auditer: le bouton « Auditer » note le site et ouvre un radar par axe avec les problèmes priorisés (du plus grave au moins grave). La pastille de score sur la carte rouvre le dernier audit."}', 'Sentinel · Auditer
Auditer: le bouton « Auditer » note le site et ouvre un radar par axe avec les problèmes priorisés (du plus grave au moins grave). La pastille de score sur la carte rouvre le dernier audit.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('928b515c-161f-40a0-ac41-2fcaa39f409c', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel · Auditer', 'Sentinel · Auditer
Auditer: le bouton « Auditer » note le site et ouvre un radar par axe avec les problèmes priorisés (du plus grave au moins grave). La pastille de score sur la carte rouvre le dernier audit.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('013d8469-480c-42fe-8afb-91977bf8245d', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel · Correctifs clé en main', '{"statement":"Correctifs clé en main: chaque problème se déplie avec les étapes pas-à-pas adaptées à votre plateforme + le code prêt à coller (bouton Copier). Pour les textes (méta description, FAQ), « Rédiger avec l''IA » génère le contenu réel, pas un gabarit."}', 'Sentinel · Correctifs clé en main
Correctifs clé en main: chaque problème se déplie avec les étapes pas-à-pas adaptées à votre plateforme + le code prêt à coller (bouton Copier). Pour les textes (méta description, FAQ), « Rédiger avec l''IA » génère le contenu réel, pas un gabarit.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('013d8469-480c-42fe-8afb-91977bf8245d', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel · Correctifs clé en main', 'Sentinel · Correctifs clé en main
Correctifs clé en main: chaque problème se déplie avec les étapes pas-à-pas adaptées à votre plateforme + le code prêt à coller (bouton Copier). Pour les textes (méta description, FAQ), « Rédiger avec l''IA » génère le contenu réel, pas un gabarit.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('de3e577e-f0bd-4988-be4c-7c5b6a13814e', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel · Visibilité IA (GEO)', '{"statement":"Visibilité IA (GEO): renseignez le nom, la ville et l''activité de l''établissement, puis « Mesurer ma visibilité IA » interroge plusieurs IA connectées au web et vous dit si vous êtes cité, à quelle position, avec quel score de citabilité."}', 'Sentinel · Visibilité IA (GEO)
Visibilité IA (GEO): renseignez le nom, la ville et l''activité de l''établissement, puis « Mesurer ma visibilité IA » interroge plusieurs IA connectées au web et vous dit si vous êtes cité, à quelle position, avec quel score de citabilité.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('de3e577e-f0bd-4988-be4c-7c5b6a13814e', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel · Visibilité IA (GEO)', 'Sentinel · Visibilité IA (GEO)
Visibilité IA (GEO): renseignez le nom, la ville et l''activité de l''établissement, puis « Mesurer ma visibilité IA » interroge plusieurs IA connectées au web et vous dit si vous êtes cité, à quelle position, avec quel score de citabilité.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('5048df8c-6656-4c18-9c36-bba8271fc22d', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel · Transmettre & archiver', '{"statement":"Transmettre & archiver: « Envoyer au webmaster » expédie le rapport (étapes + code) par e-mail; « PDF » l''exporte. Le prochain audit vérifie ce qui a été corrigé → le score remonte, la progression est prouvée."}', 'Sentinel · Transmettre & archiver
Transmettre & archiver: « Envoyer au webmaster » expédie le rapport (étapes + code) par e-mail; « PDF » l''exporte. Le prochain audit vérifie ce qui a été corrigé → le score remonte, la progression est prouvée.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('5048df8c-6656-4c18-9c36-bba8271fc22d', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel · Transmettre & archiver', 'Sentinel · Transmettre & archiver
Transmettre & archiver: « Envoyer au webmaster » expédie le rapport (étapes + code) par e-mail; « PDF » l''exporte. Le prochain audit vérifie ce qui a été corrigé → le score remonte, la progression est prouvée.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8564a15c-cdea-4f16-be16-1e131fdc7b40', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Qu''est-ce qui consomme des conversations, et qu''est-ce qui est gratuit ?', '{"question":"Qu''est-ce qui consomme des conversations, et qu''est-ce qui est gratuit ?","answer":"La surveillance, l''audit complet et les correctifs « code à coller » sont gratuits (aucune IA). Seuls « Rédiger avec l''IA » (méta description, FAQ) et la mesure de visibilité IA (GEO) consomment des conversations — environ 1 par génération ou par mesure. Avec votre propre clé moteur (votre propre clé), ces actions passent hors compteur."}', 'Qu''est-ce qui consomme des conversations, et qu''est-ce qui est gratuit ?
Qu''est-ce qui consomme des conversations, et qu''est-ce qui est gratuit ?
La surveillance, l''audit complet et les correctifs « code à coller » sont gratuits (aucune IA). Seuls « Rédiger avec l''IA » (méta description, FAQ) et la mesure de visibilité IA (GEO) consomment des conversations — environ 1 par génération ou par mesure. Avec votre propre clé moteur (votre propre clé), ces actions passent hors compteur.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8564a15c-cdea-4f16-be16-1e131fdc7b40', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Qu''est-ce qui consomme des conversations, et qu''est-ce qui est gratuit ?', 'Qu''est-ce qui consomme des conversations, et qu''est-ce qui est gratuit ?
Qu''est-ce qui consomme des conversations, et qu''est-ce qui est gratuit ?
La surveillance, l''audit complet et les correctifs « code à coller » sont gratuits (aucune IA). Seuls « Rédiger avec l''IA » (méta description, FAQ) et la mesure de visibilité IA (GEO) consomment des conversations — environ 1 par génération ou par mesure. Avec votre propre clé moteur (votre propre clé), ces actions passent hors compteur.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('e0a40817-297b-48e0-a95e-c76976b015b7', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Pourquoi l''axe « Visibilité IA (GEO) » n''apparaît-il pas ?', '{"question":"Pourquoi l''axe « Visibilité IA (GEO) » n''apparaît-il pas ?","answer":"Le GEO s''active dès qu''une clé moteur est configurée côté serveur (une clé Gemini gratuite suffit pour démarrer). Tant qu''aucune clé n''est posée, l''axe et le bouton « Mesurer » restent masqués — le reste de l''audit fonctionne normalement."}', 'Pourquoi l''axe « Visibilité IA (GEO) » n''apparaît-il pas ?
Pourquoi l''axe « Visibilité IA (GEO) » n''apparaît-il pas ?
Le GEO s''active dès qu''une clé moteur est configurée côté serveur (une clé Gemini gratuite suffit pour démarrer). Tant qu''aucune clé n''est posée, l''axe et le bouton « Mesurer » restent masqués — le reste de l''audit fonctionne normalement.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('e0a40817-297b-48e0-a95e-c76976b015b7', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Pourquoi l''axe « Visibilité IA (GEO) » n''apparaît-il pas ?', 'Pourquoi l''axe « Visibilité IA (GEO) » n''apparaît-il pas ?
Pourquoi l''axe « Visibilité IA (GEO) » n''apparaît-il pas ?
Le GEO s''active dès qu''une clé moteur est configurée côté serveur (une clé Gemini gratuite suffit pour démarrer). Tant qu''aucune clé n''est posée, l''axe et le bouton « Mesurer » restent masqués — le reste de l''audit fonctionne normalement.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('a1a2fe78-dd25-49be-a503-e7a1126cf8da', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Sentinel fonctionne-t-il avec Wix, WordPress et un site sur-mesure ?', '{"question":"Sentinel fonctionne-t-il avec Wix, WordPress et un site sur-mesure ?","answer":"Oui. Sentinel détecte la plateforme à partir du site et adapte les instructions de chaque correctif: où cliquer dans votre éditeur, ou bien le bloc de code exact à coller dans l''en-tête. C''est pensé pour un utilisateur non technique."}', 'Sentinel fonctionne-t-il avec Wix, WordPress et un site sur-mesure ?
Sentinel fonctionne-t-il avec Wix, WordPress et un site sur-mesure ?
Oui. Sentinel détecte la plateforme à partir du site et adapte les instructions de chaque correctif: où cliquer dans votre éditeur, ou bien le bloc de code exact à coller dans l''en-tête. C''est pensé pour un utilisateur non technique.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('a1a2fe78-dd25-49be-a503-e7a1126cf8da', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel fonctionne-t-il avec Wix, WordPress et un site sur-mesure ?', 'Sentinel fonctionne-t-il avec Wix, WordPress et un site sur-mesure ?
Sentinel fonctionne-t-il avec Wix, WordPress et un site sur-mesure ?
Oui. Sentinel détecte la plateforme à partir du site et adapte les instructions de chaque correctif: où cliquer dans votre éditeur, ou bien le bloc de code exact à coller dans l''en-tête. C''est pensé pour un utilisateur non technique.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('86f6eeed-8cda-4802-874c-c2a7cb170fa1', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Pourquoi je ne vois pas le nombre de jours avant l''expiration du certificat SSL ?', '{"question":"Pourquoi je ne vois pas le nombre de jours avant l''expiration du certificat SSL ?","answer":"Un site en HTTPS qui répond a un certificat valide à l''instant de la vérification. Le compte à rebours précis (J-14) n''est pas lisible de manière souveraine par notre sonde; il sera ajouté via une vérification dédiée. En attendant, une chute du HTTPS est détectée par la veille."}', 'Pourquoi je ne vois pas le nombre de jours avant l''expiration du certificat SSL ?
Pourquoi je ne vois pas le nombre de jours avant l''expiration du certificat SSL ?
Un site en HTTPS qui répond a un certificat valide à l''instant de la vérification. Le compte à rebours précis (J-14) n''est pas lisible de manière souveraine par notre sonde; il sera ajouté via une vérification dédiée. En attendant, une chute du HTTPS est détectée par la veille.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('86f6eeed-8cda-4802-874c-c2a7cb170fa1', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Pourquoi je ne vois pas le nombre de jours avant l''expiration du certificat SSL ?', 'Pourquoi je ne vois pas le nombre de jours avant l''expiration du certificat SSL ?
Pourquoi je ne vois pas le nombre de jours avant l''expiration du certificat SSL ?
Un site en HTTPS qui répond a un certificat valide à l''instant de la vérification. Le compte à rebours précis (J-14) n''est pas lisible de manière souveraine par notre sonde; il sera ajouté via une vérification dédiée. En attendant, une chute du HTTPS est détectée par la veille.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('1bfd08d6-d8ce-4801-8474-744ac0075c08', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Que reçoit mon webmaster par e-mail ?', '{"question":"Que reçoit mon webmaster par e-mail ?","answer":"Le rapport complet: le score, les problèmes classés par priorité, les étapes adaptées à la plateforme et le code prêt à coller. L''envoi e-mail s''active côté serveur; tant qu''il ne l''est pas, le bouton reste masqué et l''export PDF prend le relais."}', 'Que reçoit mon webmaster par e-mail ?
Que reçoit mon webmaster par e-mail ?
Le rapport complet: le score, les problèmes classés par priorité, les étapes adaptées à la plateforme et le code prêt à coller. L''envoi e-mail s''active côté serveur; tant qu''il ne l''est pas, le bouton reste masqué et l''export PDF prend le relais.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('1bfd08d6-d8ce-4801-8474-744ac0075c08', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Que reçoit mon webmaster par e-mail ?', 'Que reçoit mon webmaster par e-mail ?
Que reçoit mon webmaster par e-mail ?
Le rapport complet: le score, les problèmes classés par priorité, les étapes adaptées à la plateforme et le code prêt à coller. L''envoi e-mail s''active côté serveur; tant qu''il ne l''est pas, le bouton reste masqué et l''export PDF prend le relais.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('409d73de-150c-4a0c-9d1b-447932740c91', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel — Comment une IA choisit qui citer', '{"statement":"Une identité claire et cohérente: même nom, adresse et téléphone partout (site, annuaires, fiche Google), reliés à votre fiche légale officielle. Des données structurées (schema.org) qui disent qui vous êtes et ce que vous faites. Des sources tierces qui parlent de vous — avis, annuaires, presse: les IA s''y fient plus qu''à votre propre site. Du contenu qui répond aux vraies questions de vos clients, pas seulement des pages de vente. Des avis récents et une présence locale soignée."}', 'Sentinel — Comment une IA choisit qui citer
Une identité claire et cohérente: même nom, adresse et téléphone partout (site, annuaires, fiche Google), reliés à votre fiche légale officielle. Des données structurées (schema.org) qui disent qui vous êtes et ce que vous faites. Des sources tierces qui parlent de vous — avis, annuaires, presse: les IA s''y fient plus qu''à votre propre site. Du contenu qui répond aux vraies questions de vos clients, pas seulement des pages de vente. Des avis récents et une présence locale soignée.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('409d73de-150c-4a0c-9d1b-447932740c91', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel — Comment une IA choisit qui citer', 'Sentinel — Comment une IA choisit qui citer
Une identité claire et cohérente: même nom, adresse et téléphone partout (site, annuaires, fiche Google), reliés à votre fiche légale officielle. Des données structurées (schema.org) qui disent qui vous êtes et ce que vous faites. Des sources tierces qui parlent de vous — avis, annuaires, presse: les IA s''y fient plus qu''à votre propre site. Du contenu qui répond aux vraies questions de vos clients, pas seulement des pages de vente. Des avis récents et une présence locale soignée.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('622d818c-1717-4601-acae-a9cf92c2bda5', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel — Par où commencer', '{"statement":"Assurez-vous que le nom de votre entreprise renvoie sans ambiguïté à une seule entité, publiez vos mentions légales et votre politique de confidentialité, créez votre fiche d''établissement, et récoltez des avis authentiques. Puis écrivez quelques pages qui répondent aux questions que vos clients posent réellement."}', 'Sentinel — Par où commencer
Assurez-vous que le nom de votre entreprise renvoie sans ambiguïté à une seule entité, publiez vos mentions légales et votre politique de confidentialité, créez votre fiche d''établissement, et récoltez des avis authentiques. Puis écrivez quelques pages qui répondent aux questions que vos clients posent réellement.', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('622d818c-1717-4601-acae-a9cf92c2bda5', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel — Par où commencer', 'Sentinel — Par où commencer
Assurez-vous que le nom de votre entreprise renvoie sans ambiguïté à une seule entité, publiez vos mentions légales et votre politique de confidentialité, créez votre fiche d''établissement, et récoltez des avis authentiques. Puis écrivez quelques pages qui répondent aux questions que vos clients posent réellement.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('c70338d0-6c07-4d03-8017-0cc7b53f093a', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Sentinel — Comment savoir si ça marche', '{"statement":"La seule façon de le savoir, c''est de mesurer: poser la question à plusieurs IA et regarder si vous êtes cité, et sur quelles requêtes. C''est exactement ce que fait Sentinel — il suit votre visibilité dans les IA dans le temps, en plus de l''audit web classique (disponibilité, SEO, sécurité, accessibilité)."}', 'Sentinel — Comment savoir si ça marche
La seule façon de le savoir, c''est de mesurer: poser la question à plusieurs IA et regarder si vous êtes cité, et sur quelles requêtes. C''est exactement ce que fait Sentinel — il suit votre visibilité dans les IA dans le temps, en plus de l''audit web classique (disponibilité, SEO, sécurité, accessibilité).', 'validated', 'import', 'apps:sentinel', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('c70338d0-6c07-4d03-8017-0cc7b53f093a', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Sentinel — Comment savoir si ça marche', 'Sentinel — Comment savoir si ça marche
La seule façon de le savoir, c''est de mesurer: poser la question à plusieurs IA et regarder si vous êtes cité, et sur quelles requêtes. C''est exactement ce que fait Sentinel — il suit votre visibilité dans les IA dans le temps, en plus de l''audit web classique (disponibilité, SEO, sécurité, accessibilité).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('b3ba3f5e-ef50-4ebf-b7b3-cd39a2221055', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Smart Agent, en une phrase', '{"term":"Smart Agent","definition":"Votre jumeau numérique de savoir-faire. Un agent qui répond à vos clients UNIQUEMENT depuis le savoir que vous avez validé — jamais d''invention: s''il ne sait pas, il le dit, et la question rejoint sa liste de travail. Vous le nourrissez (texte, page web, fichier, interview guidée), vous le testez, puis vous le publiez par lien ou QR code: vos visiteurs lui parlent sans compte, à l''écrit ou à la voix."}', 'Smart Agent, en une phrase
Smart Agent
Votre jumeau numérique de savoir-faire. Un agent qui répond à vos clients UNIQUEMENT depuis le savoir que vous avez validé — jamais d''invention: s''il ne sait pas, il le dit, et la question rejoint sa liste de travail. Vous le nourrissez (texte, page web, fichier, interview guidée), vous le testez, puis vous le publiez par lien ou QR code: vos visiteurs lui parlent sans compte, à l''écrit ou à la voix.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('b3ba3f5e-ef50-4ebf-b7b3-cd39a2221055', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Agent, en une phrase', 'Smart Agent, en une phrase
Smart Agent
Votre jumeau numérique de savoir-faire. Un agent qui répond à vos clients UNIQUEMENT depuis le savoir que vous avez validé — jamais d''invention: s''il ne sait pas, il le dit, et la question rejoint sa liste de travail. Vous le nourrissez (texte, page web, fichier, interview guidée), vous le testez, puis vous le publiez par lien ou QR code: vos visiteurs lui parlent sans compte, à l''écrit ou à la voix.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('6a72dd7d-a547-429a-9bb2-dba2c7885c86', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent · Créer l''agent', '{"statement":"Créer l''agent: « Nouvel agent » → partez d''un gabarit métier (vendeur, agent immobilier, gardien de musée, concierge, guide, SAV…) qui pré-remplit son rôle, son style et son objectif. Tout reste modifiable dans Réglages."}', 'Smart Agent · Créer l''agent
Créer l''agent: « Nouvel agent » → partez d''un gabarit métier (vendeur, agent immobilier, gardien de musée, concierge, guide, SAV…) qui pré-remplit son rôle, son style et son objectif. Tout reste modifiable dans Réglages.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('6a72dd7d-a547-429a-9bb2-dba2c7885c86', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Agent · Créer l''agent', 'Smart Agent · Créer l''agent
Créer l''agent: « Nouvel agent » → partez d''un gabarit métier (vendeur, agent immobilier, gardien de musée, concierge, guide, SAV…) qui pré-remplit son rôle, son style et son objectif. Tout reste modifiable dans Réglages.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('8525d134-59d4-4f02-9649-5c897fcacde8', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent · Le nourrir', '{"statement":"Le nourrir: onglet Savoir → « Démarrer avec un pack métier » installe des fiches de savoir-faire prêtes à relire, et « Répondre aux questions du métier » lance l''interview guidée: vous répondez à l''oral ou au clavier, l''IA structure en fiches. « Nourrir le coffre » accepte aussi un texte collé, une page de votre site ou un fichier (PDF, Word, Excel…)."}', 'Smart Agent · Le nourrir
Le nourrir: onglet Savoir → « Démarrer avec un pack métier » installe des fiches de savoir-faire prêtes à relire, et « Répondre aux questions du métier » lance l''interview guidée: vous répondez à l''oral ou au clavier, l''IA structure en fiches. « Nourrir le coffre » accepte aussi un texte collé, une page de votre site ou un fichier (PDF, Word, Excel…).', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('8525d134-59d4-4f02-9649-5c897fcacde8', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Agent · Le nourrir', 'Smart Agent · Le nourrir
Le nourrir: onglet Savoir → « Démarrer avec un pack métier » installe des fiches de savoir-faire prêtes à relire, et « Répondre aux questions du métier » lance l''interview guidée: vous répondez à l''oral ou au clavier, l''IA structure en fiches. « Nourrir le coffre » accepte aussi un texte collé, une page de votre site ou un fichier (PDF, Word, Excel…).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('ac51039b-814c-491b-a631-999b50807059', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent · Valider', '{"statement":"Valider: une fiche ne sert l''agent que si VOUS l''avez validée. Les fiches en brouillon (dont celles des packs, à personnaliser: remplacez les [crochets]) sont inactives tant qu''elles ne sont pas validées."}', 'Smart Agent · Valider
Valider: une fiche ne sert l''agent que si VOUS l''avez validée. Les fiches en brouillon (dont celles des packs, à personnaliser: remplacez les [crochets]) sont inactives tant qu''elles ne sont pas validées.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('ac51039b-814c-491b-a631-999b50807059', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Agent · Valider', 'Smart Agent · Valider
Valider: une fiche ne sert l''agent que si VOUS l''avez validée. Les fiches en brouillon (dont celles des packs, à personnaliser: remplacez les [crochets]) sont inactives tant qu''elles ne sont pas validées.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('5903c24d-0665-4125-955b-9f0149afad98', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent · Tester', '{"statement":"Tester: l''onglet Tester est votre bac à sable — chaque réponse cite ses fiches sources, et le haut-parleur lit les réponses avec la voix neuronale Siwis. Les « Tests étalons » vérifient en un clic que l''agent répond là où il doit, et se tait là où il faut."}', 'Smart Agent · Tester
Tester: l''onglet Tester est votre bac à sable — chaque réponse cite ses fiches sources, et le haut-parleur lit les réponses avec la voix neuronale Siwis. Les « Tests étalons » vérifient en un clic que l''agent répond là où il doit, et se tait là où il faut.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('5903c24d-0665-4125-955b-9f0149afad98', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Agent · Tester', 'Smart Agent · Tester
Tester: l''onglet Tester est votre bac à sable — chaque réponse cite ses fiches sources, et le haut-parleur lit les réponses avec la voix neuronale Siwis. Les « Tests étalons » vérifient en un clic que l''agent répond là où il doit, et se tait là où il faut.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('0fe057ea-3b91-47cc-800f-466843558959', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent · Combler les trous', '{"statement":"Combler les trous: quand l''agent sèche (chez vous ou face à un visiteur), la question atterrit dans l''onglet Trous, les reformulations d''une même question se cumulent. « Démarrer l''interview » les comble une par une, les plus demandées d''abord."}', 'Smart Agent · Combler les trous
Combler les trous: quand l''agent sèche (chez vous ou face à un visiteur), la question atterrit dans l''onglet Trous, les reformulations d''une même question se cumulent. « Démarrer l''interview » les comble une par une, les plus demandées d''abord.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('0fe057ea-3b91-47cc-800f-466843558959', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Agent · Combler les trous', 'Smart Agent · Combler les trous
Combler les trous: quand l''agent sèche (chez vous ou face à un visiteur), la question atterrit dans l''onglet Trous, les reformulations d''une même question se cumulent. « Démarrer l''interview » les comble une par une, les plus demandées d''abord.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('7da78af3-864f-4617-9a27-f3aeb92e9101', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent · Publier', '{"statement":"Publier: Réglages → « Publier cet agent » → lien public + QR code à imprimer. Vos visiteurs lui parlent sans compte; vous suivez le nombre de questions, le plafond par jour et l''expiration du lien."}', 'Smart Agent · Publier
Publier: Réglages → « Publier cet agent » → lien public + QR code à imprimer. Vos visiteurs lui parlent sans compte; vous suivez le nombre de questions, le plafond par jour et l''expiration du lien.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('7da78af3-864f-4617-9a27-f3aeb92e9101', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Agent · Publier', 'Smart Agent · Publier
Publier: Réglages → « Publier cet agent » → lien public + QR code à imprimer. Vos visiteurs lui parlent sans compte; vous suivez le nombre de questions, le plafond par jour et l''expiration du lien.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('7131d67a-d614-48c6-808d-7d75ccc79641', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'L''agent peut-il inventer une réponse ?', '{"question":"L''agent peut-il inventer une réponse ?","answer":"Non, c''est le principe fondateur: il ne répond que depuis vos fiches validées, en les citant (dans le bac à sable). Hors de son savoir, il le dit avec ses mots — sans rien inventer — et la question rejoint ses Trous pour que vous puissiez la combler."}', 'L''agent peut-il inventer une réponse ?
L''agent peut-il inventer une réponse ?
Non, c''est le principe fondateur: il ne répond que depuis vos fiches validées, en les citant (dans le bac à sable). Hors de son savoir, il le dit avec ses mots — sans rien inventer — et la question rejoint ses Trous pour que vous puissiez la combler.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('7131d67a-d614-48c6-808d-7d75ccc79641', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'L''agent peut-il inventer une réponse ?', 'L''agent peut-il inventer une réponse ?
L''agent peut-il inventer une réponse ?
Non, c''est le principe fondateur: il ne répond que depuis vos fiches validées, en les citant (dans le bac à sable). Hors de son savoir, il le dit avec ses mots — sans rien inventer — et la question rejoint ses Trous pour que vous puissiez la combler.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('478914bb-506a-44ed-9daa-0fcb06f9c8c2', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Qu''est-ce qui consomme mes conversations ?', '{"question":"Qu''est-ce qui consomme mes conversations ?","answer":"Une question posée à l''agent (par vous ou un visiteur public) et une extraction de fiches (coller un texte, lire une page web ou un fichier, structurer une réponse d''interview): 1 conversation chacune. Quand l''agent ne sait pas répondre sans génération, la conversation est rendue. La lecture vocale, la dictée et le correcteur de trous sont gratuits."}', 'Qu''est-ce qui consomme mes conversations ?
Qu''est-ce qui consomme mes conversations ?
Une question posée à l''agent (par vous ou un visiteur public) et une extraction de fiches (coller un texte, lire une page web ou un fichier, structurer une réponse d''interview): 1 conversation chacune. Quand l''agent ne sait pas répondre sans génération, la conversation est rendue. La lecture vocale, la dictée et le correcteur de trous sont gratuits.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('478914bb-506a-44ed-9daa-0fcb06f9c8c2', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Qu''est-ce qui consomme mes conversations ?', 'Qu''est-ce qui consomme mes conversations ?
Qu''est-ce qui consomme mes conversations ?
Une question posée à l''agent (par vous ou un visiteur public) et une extraction de fiches (coller un texte, lire une page web ou un fichier, structurer une réponse d''interview): 1 conversation chacune. Quand l''agent ne sait pas répondre sans génération, la conversation est rendue. La lecture vocale, la dictée et le correcteur de trous sont gratuits.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('01f5d2ef-e2d0-4749-9ef3-f45a19884744', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Que voient mes visiteurs sur la page publique ?', '{"question":"Que voient mes visiteurs sur la page publique ?","answer":"Le nom de l''agent, son métier, son message d''accueil et ses réponses — jamais vos fiches, vos sources ni votre coffre. Leurs questions ne sont pas rattachées à leur identité et sont effacées après 90 jours."}', 'Que voient mes visiteurs sur la page publique ?
Que voient mes visiteurs sur la page publique ?
Le nom de l''agent, son métier, son message d''accueil et ses réponses — jamais vos fiches, vos sources ni votre coffre. Leurs questions ne sont pas rattachées à leur identité et sont effacées après 90 jours.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('01f5d2ef-e2d0-4749-9ef3-f45a19884744', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Que voient mes visiteurs sur la page publique ?', 'Que voient mes visiteurs sur la page publique ?
Que voient mes visiteurs sur la page publique ?
Le nom de l''agent, son métier, son message d''accueil et ses réponses — jamais vos fiches, vos sources ni votre coffre. Leurs questions ne sont pas rattachées à leur identité et sont effacées après 90 jours.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('325b9587-821f-438a-b84d-e31a2639f6f3', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'Un visiteur peut-il épuiser mes conversations ?', '{"question":"Un visiteur peut-il épuiser mes conversations ?","answer":"Des garde-fous limitent chaque appareil (50 questions/jour) et chaque lien (plafond quotidien réglable dans Réglages → Publier, 500 par défaut). Vous pouvez aussi fixer une date d''expiration ou dépublier à tout moment — le lien et le QR cessent immédiatement de fonctionner."}', 'Un visiteur peut-il épuiser mes conversations ?
Un visiteur peut-il épuiser mes conversations ?
Des garde-fous limitent chaque appareil (50 questions/jour) et chaque lien (plafond quotidien réglable dans Réglages → Publier, 500 par défaut). Vous pouvez aussi fixer une date d''expiration ou dépublier à tout moment — le lien et le QR cessent immédiatement de fonctionner.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('325b9587-821f-438a-b84d-e31a2639f6f3', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Un visiteur peut-il épuiser mes conversations ?', 'Un visiteur peut-il épuiser mes conversations ?
Un visiteur peut-il épuiser mes conversations ?
Des garde-fous limitent chaque appareil (50 questions/jour) et chaque lien (plafond quotidien réglable dans Réglages → Publier, 500 par défaut). Vous pouvez aussi fixer une date d''expiration ou dépublier à tout moment — le lien et le QR cessent immédiatement de fonctionner.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('b21b4f68-99f5-40d1-aad6-2e5501f24c94', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'À quoi servent le coffre partagé et les dossiers ?', '{"question":"À quoi servent le coffre partagé et les dossiers ?","answer":"Un dossier regroupe des agents (par établissement, par équipe…). Son coffre partagé contient le savoir commun à tous ses agents (horaires, règles maison): chaque agent lit son coffre privé ET le coffre partagé de son dossier."}', 'À quoi servent le coffre partagé et les dossiers ?
À quoi servent le coffre partagé et les dossiers ?
Un dossier regroupe des agents (par établissement, par équipe…). Son coffre partagé contient le savoir commun à tous ses agents (horaires, règles maison): chaque agent lit son coffre privé ET le coffre partagé de son dossier.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('b21b4f68-99f5-40d1-aad6-2e5501f24c94', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'À quoi servent le coffre partagé et les dossiers ?', 'À quoi servent le coffre partagé et les dossiers ?
À quoi servent le coffre partagé et les dossiers ?
Un dossier regroupe des agents (par établissement, par équipe…). Son coffre partagé contient le savoir commun à tous ses agents (horaires, règles maison): chaque agent lit son coffre privé ET le coffre partagé de son dossier.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('fab14a6a-38fc-40a8-b00f-8499d765d29e', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'qa', 'La voix et la dictée sont-elles payantes ?', '{"question":"La voix et la dictée sont-elles payantes ?","answer":"Non. La dictée utilise la reconnaissance vocale de votre navigateur, et la lecture utilise Siwis, une voix neuronale française hébergée par Keystone, exécutée dans votre navigateur (premier chargement d''environ 60 Mo, puis en cache). Aucun coût IA récurrent."}', 'La voix et la dictée sont-elles payantes ?
La voix et la dictée sont-elles payantes ?
Non. La dictée utilise la reconnaissance vocale de votre navigateur, et la lecture utilise Siwis, une voix neuronale française hébergée par Keystone, exécutée dans votre navigateur (premier chargement d''environ 60 Mo, puis en cache). Aucun coût IA récurrent.', 'validated', 'import', 'apps:smart-agent', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('fab14a6a-38fc-40a8-b00f-8499d765d29e', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'La voix et la dictée sont-elles payantes ?', 'La voix et la dictée sont-elles payantes ?
La voix et la dictée sont-elles payantes ?
Non. La dictée utilise la reconnaissance vocale de votre navigateur, et la lecture utilise Siwis, une voix neuronale française hébergée par Keystone, exécutée dans votre navigateur (premier chargement d''environ 60 Mo, puis en cache). Aucun coût IA récurrent.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('7285fb54-5180-4e15-b344-9a8f9575ac12', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent — Pourquoi une IA invente', '{"statement":"Un modèle de langage ne consulte pas une base de vérité: il prédit la suite de mots la plus probable. Sans cadre, il puise dans des connaissances générales, périmées ou inadaptées à votre activité. Le problème n''est pas l''IA en soi, c''est de la laisser répondre sans source."}', 'Smart Agent — Pourquoi une IA invente
Un modèle de langage ne consulte pas une base de vérité: il prédit la suite de mots la plus probable. Sans cadre, il puise dans des connaissances générales, périmées ou inadaptées à votre activité. Le problème n''est pas l''IA en soi, c''est de la laisser répondre sans source.', 'validated', 'import', 'apps:smart-agent', 'fr');
