INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('56eb16a6-c663-452a-89ab-f89c21c63ab8', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Agent — Ce que ça apporte concrètement', '{"statement":"Vos clients obtiennent une réponse fiable à toute heure, sans que vous ayez à surveiller chaque échange. Vous gardez la main sur ce qui est dit en votre nom, et vous repérez les questions sans réponse — celles qui révèlent un trou dans votre information. Smart Agent repose exactement sur ce principe: un agent ancré sur votre savoir-faire, qui cite ses sources et préfère se taire plutôt qu''inventer."}', 'Smart Agent — Ce que ça apporte concrètement
Vos clients obtiennent une réponse fiable à toute heure, sans que vous ayez à surveiller chaque échange. Vous gardez la main sur ce qui est dit en votre nom, et vous repérez les questions sans réponse — celles qui révèlent un trou dans votre information. Smart Agent repose exactement sur ce principe: un agent ancré sur votre savoir-faire, qui cite ses sources et préfère se taire plutôt qu''inventer.', 'validated', 'import', 'apps:smart-agent', 'fr');
