INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('4774fc42-f0e2-4b58-85ec-e21b71bed679', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Dynamic QR — Le QR statique', '{"statement":"L''adresse (URL, texte, Wi-Fi…) est encodée directement dans le motif. Avantage: il fonctionne pour toujours, sans dépendre d''aucun service. Inconvénient: impossible à modifier une fois imprimé. Si l''adresse change, le QR est bon à jeter."}', 'Smart Dynamic QR — Le QR statique
L''adresse (URL, texte, Wi-Fi…) est encodée directement dans le motif. Avantage: il fonctionne pour toujours, sans dépendre d''aucun service. Inconvénient: impossible à modifier une fois imprimé. Si l''adresse change, le QR est bon à jeter.', 'validated', 'import', 'apps:smart-qr', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('4774fc42-f0e2-4b58-85ec-e21b71bed679', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Dynamic QR — Le QR statique', 'Smart Dynamic QR — Le QR statique
