INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('fa80f682-bb17-48c2-bd0b-e87ef2fe01b5', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Dynamic QR — Le QR dynamique', '{"statement":"Le motif pointe vers une redirection que vous contrôlez. Vous pouvez changer la destination après impression, autant de fois que vous voulez, sans réimprimer. Bonus: chaque scan peut être compté."}', 'Smart Dynamic QR — Le QR dynamique
Le motif pointe vers une redirection que vous contrôlez. Vous pouvez changer la destination après impression, autant de fois que vous voulez, sans réimprimer. Bonus: chaque scan peut être compté.', 'validated', 'import', 'apps:smart-qr', 'fr');
