INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('77b8a488-1593-4671-b22e-0a2f417e1eff', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Dynamic QR — Lequel pour quel usage', '{"statement":"Statique: une information qui ne changera jamais (un accès Wi-Fi, une carte de visite simple). Dynamique: tout ce qui est imprimé en quantité ou destiné à durer — bâche de chantier, flyer réutilisé, étiquette produit, menu, affiche d''événement."}', 'Smart Dynamic QR — Lequel pour quel usage
Statique: une information qui ne changera jamais (un accès Wi-Fi, une carte de visite simple). Dynamique: tout ce qui est imprimé en quantité ou destiné à durer — bâche de chantier, flyer réutilisé, étiquette produit, menu, affiche d''événement.', 'validated', 'import', 'apps:smart-qr', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('77b8a488-1593-4671-b22e-0a2f417e1eff', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Dynamic QR — Lequel pour quel usage', 'Smart Dynamic QR — Lequel pour quel usage
Statique: une information qui ne changera jamais (un accès Wi-Fi, une carte de visite simple). Dynamique: tout ce qui est imprimé en quantité ou destiné à durer — bâche de chantier, flyer réutilisé, étiquette produit, menu, affiche d''événement.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('f8f23fd3-d2cd-431a-82f6-a17afafdae55', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Smart Dynamic QR — Et le RGPD ?', '{"statement":"Compter les scans implique un traitement de données. Méfiez-vous des générateurs gratuits qui revendent ces données ou passent par Google. Un bon QR dynamique trace les scans de façon anonyme et conforme, sans cookie ni revente — c''est l''approche de Smart Dynamic QR."}', 'Smart Dynamic QR — Et le RGPD ?
Compter les scans implique un traitement de données. Méfiez-vous des générateurs gratuits qui revendent ces données ou passent par Google. Un bon QR dynamique trace les scans de façon anonyme et conforme, sans cookie ni revente — c''est l''approche de Smart Dynamic QR.', 'validated', 'import', 'apps:smart-qr', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('f8f23fd3-d2cd-431a-82f6-a17afafdae55', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Smart Dynamic QR — Et le RGPD ?', 'Smart Dynamic QR — Et le RGPD ?
Compter les scans implique un traitement de données. Méfiez-vous des générateurs gratuits qui revendent ces données ou passent par Google. Un bon QR dynamique trace les scans de façon anonyme et conforme, sans cookie ni revente — c''est l''approche de Smart Dynamic QR.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('c75290e6-3f78-42e2-be63-aa4a68581257', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'definition', 'Social Manager, en une phrase', '{"term":"Social Manager","definition":"Votre régie de publication. Écrivez une fois, publiez sur Facebook, Instagram, Threads et Telegram — tout de suite ou à l''heure programmée. Le composer vérifie les contraintes de chaque réseau avant l''envoi, la file de publication montre ce qui part et ce qui est parti, et en cas de pépin réseau l''envoi se retente tout seul, uniquement sur les réseaux qui ont échoué."}', 'Social Manager, en une phrase
Social Manager
Votre régie de publication. Écrivez une fois, publiez sur Facebook, Instagram, Threads et Telegram — tout de suite ou à l''heure programmée. Le composer vérifie les contraintes de chaque réseau avant l''envoi, la file de publication montre ce qui part et ce qui est parti, et en cas de pépin réseau l''envoi se retente tout seul, uniquement sur les réseaux qui ont échoué.', 'validated', 'import', 'apps:social-manager', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('c75290e6-3f78-42e2-be63-aa4a68581257', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Social Manager, en une phrase', 'Social Manager, en une phrase
Social Manager
Votre régie de publication. Écrivez une fois, publiez sur Facebook, Instagram, Threads et Telegram — tout de suite ou à l''heure programmée. Le composer vérifie les contraintes de chaque réseau avant l''envoi, la file de publication montre ce qui part et ce qui est parti, et en cas de pépin réseau l''envoi se retente tout seul, uniquement sur les réseaux qui ont échoué.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('051490ec-0d2a-480f-8a12-ea57907e0b3f', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Social Manager · Connecter vos comptes', '{"statement":"Connecter vos comptes: « Connecter un réseau » → Telegram se branche en quelques minutes (assistant pas à pas), Facebook, Instagram et Threads passent par une connexion officielle en deux clics (aucun mot de passe à confier à Keystone)."}', 'Social Manager · Connecter vos comptes
Connecter vos comptes: « Connecter un réseau » → Telegram se branche en quelques minutes (assistant pas à pas), Facebook, Instagram et Threads passent par une connexion officielle en deux clics (aucun mot de passe à confier à Keystone).', 'validated', 'import', 'apps:social-manager', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('051490ec-0d2a-480f-8a12-ea57907e0b3f', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Social Manager · Connecter vos comptes', 'Social Manager · Connecter vos comptes
Connecter vos comptes: « Connecter un réseau » → Telegram se branche en quelques minutes (assistant pas à pas), Facebook, Instagram et Threads passent par une connexion officielle en deux clics (aucun mot de passe à confier à Keystone).');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('6c475ef3-c427-4d85-92b7-78138f931dd2', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Social Manager · Composer', '{"statement":"Composer: écrivez votre texte, ajoutez une image, cochez les réseaux de destination. L''aperçu signale en rouge ce qu''un réseau n''acceptera pas (longueur, image manquante…) avant même d''envoyer."}', 'Social Manager · Composer
Composer: écrivez votre texte, ajoutez une image, cochez les réseaux de destination. L''aperçu signale en rouge ce qu''un réseau n''acceptera pas (longueur, image manquante…) avant même d''envoyer.', 'validated', 'import', 'apps:social-manager', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('6c475ef3-c427-4d85-92b7-78138f931dd2', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Social Manager · Composer', 'Social Manager · Composer
Composer: écrivez votre texte, ajoutez une image, cochez les réseaux de destination. L''aperçu signale en rouge ce qu''un réseau n''acceptera pas (longueur, image manquante…) avant même d''envoyer.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('d1936047-f6a2-4bfc-80d2-8493bb87cce2', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Social Manager · « Publier maintenant » ou « Programmer…', '{"statement":"« Publier maintenant » ou « Programmer… »: choisissez le jour et l''heure — le post part tout seul, même dashboard fermé."}', 'Social Manager · « Publier maintenant » ou « Programmer…
« Publier maintenant » ou « Programmer… »: choisissez le jour et l''heure — le post part tout seul, même dashboard fermé.', 'validated', 'import', 'apps:social-manager', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('d1936047-f6a2-4bfc-80d2-8493bb87cce2', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Social Manager · « Publier maintenant » ou « Programmer…', 'Social Manager · « Publier maintenant » ou « Programmer…
« Publier maintenant » ou « Programmer… »: choisissez le jour et l''heure — le post part tout seul, même dashboard fermé.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('00ebe6b1-63a2-4964-a25a-7413b7991d70', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Social Manager · La file de publication', '{"statement":"La file de publication: posts programmés (annulables), posts envoyés avec lien « voir le post », et bouton « Renvoyer » si un réseau a échoué après les réessais automatiques."}', 'Social Manager · La file de publication
La file de publication: posts programmés (annulables), posts envoyés avec lien « voir le post », et bouton « Renvoyer » si un réseau a échoué après les réessais automatiques.', 'validated', 'import', 'apps:social-manager', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('00ebe6b1-63a2-4964-a25a-7413b7991d70', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Social Manager · La file de publication', 'Social Manager · La file de publication
La file de publication: posts programmés (annulables), posts envoyés avec lien « voir le post », et bouton « Renvoyer » si un réseau a échoué après les réessais automatiques.');
INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('d3d88b70-6249-4608-b996-695f5686c973', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Social Manager · Santé des connexions', '{"statement":"Santé des connexions: si un compte expire (mot de passe changé, autorisation révoquée), un bandeau vous prévient — un clic pour reconnecter, sans rien perdre."}', 'Social Manager · Santé des connexions
Santé des connexions: si un compte expire (mot de passe changé, autorisation révoquée), un bandeau vous prévient — un clic pour reconnecter, sans rien perdre.', 'validated', 'import', 'apps:social-manager', 'fr');
INSERT INTO kortex_units_fts_v2 (unit_id, tenant_id, vault_id, title, body_text) VALUES ('d3d88b70-6249-4608-b996-695f5686c973', 'default', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'Social Manager · Santé des connexions', 'Social Manager · Santé des connexions
