INSERT INTO kortex_units (id, tenant_id, agent_id, vault_id, type, title, body, body_text, status, source_kind, source_ref, lang) VALUES ('153ac1a7-3259-4402-a33d-9f1b1907ec87', 'default', '4c2691e8-085b-409b-af80-f8ca441c96db', 'e1dccc3c-7656-4957-bd07-7421857b696c', 'fact', 'Social Manager — Réutiliser ce qui marche', '{"statement":"Vous n''avez pas besoin d''une idée neuve à chaque fois. Une question fréquente de vos clients, une coulisse de votre métier, un avis reçu, une réponse à une objection courante: ce sont des publications. Gardez sous la main une réserve de ces formats simples et puisez dedans quand l''inspiration manque. L''objectif n''est pas de devenir community manager, mais de rester visible sans y sacrifier votre métier. Social Manager réunit ces réflexes: un message écrit une fois, adapté et publié sur vos réseaux, programmé à l''avance."}', 'Social Manager — Réutiliser ce qui marche
Vous n''avez pas besoin d''une idée neuve à chaque fois. Une question fréquente de vos clients, une coulisse de votre métier, un avis reçu, une réponse à une objection courante: ce sont des publications. Gardez sous la main une réserve de ces formats simples et puisez dedans quand l''inspiration manque. L''objectif n''est pas de devenir community manager, mais de rester visible sans y sacrifier votre métier. Social Manager réunit ces réflexes: un message écrit une fois, adapté et publié sur vos réseaux, programmé à l''avance.', 'validated', 'import', 'apps:social-manager', 'fr');
